export const EXT_TERMS_6: GlossaryTerm[] = [
  // ===== 易学深化 · 河洛数与先天数 (6) =====
  {slug:'hetu',name:'河图',pinyin:'Hé Tú',english:'Yellow River Diagram',category:'yijing',shortDesc:'相传龙马负出的图式，一至十数分五行生成之位，主生成。',detail:'河图传说为伏羲时黄河龙马所负之图，由白点（阳）与黑点（阴）布列一至十数而成：一六共宗居北方属水，二七为朋居南方属火，三八同道居东方属木，四九为友居西方属金，五十同途居中央属土。其中一三五七九为生数（天一生水、地二生火、天三生木、地四生金、天五生土），二四六八十为成数（地六成之、天七成之、地八成之、天九成之、地十成之），生数加五即成数。河图之数即系辞所言之天地之数，主五行的生成次序，为易学象数之源。',related:['hetuluoshu','tiandi-zhi-shu','xiantian-bagua']},
  {slug:'luoshu',name:'洛书',pinyin:'Luò Shū',english:'Luo River Writing',category:'yijing',shortDesc:'相传神龟负出的图式，一至九数布九宫，纵横皆十五，主变化。',detail:'洛书传说为大禹时洛水神龟所负之书，以一至九数布列九宫，口诀「戴九履一，左三右七，二四为肩，六八为足，五居中央」。其数横、竖、斜相加皆为十五，阴阳奇偶相配，运行周流，故主变化与流行。洛书九宫与后天八卦相配：坎一、坤二、震三、巽四、中五、乾六、兑七、艮八、离九，为奇门遁甲、九宫飞星、三元风水等术数的数理框架，也即后天卦数。河图为体主生成，洛书为用主变化，合称河洛。',related:['hetuluoshu','houtian-bagua','jiugong']},
  {slug:'xiantian-guashu',name:'先天卦数',pinyin:'Xiān Tiān Guà Shù',english:'Former-Heaven Trigram Numbers',category:'yijing',shortDesc:'先天八卦所配之数：乾一兑二离三震四巽五坎六艮七坤八。',detail:'先天卦数又称先天数、伏羲八卦数，即先天八卦方位所配的卦序数：乾一、兑二、离三、震四、巽五、坎六、艮七、坤八，语出邵雍《皇极经世》。其数自乾一始，依「天地定位」左右分行：左边乾兑离震为阳仪，数顺而进；右边巽坎艮坤为阴仪，数亦顺承，合之恰成对待之序。先天数用于梅花易数起卦（取上下卦数加时数成卦）、推演气数与先天命理，与洛书之后天卦数（坎一坤二等）相对而用，先天为体、后天为用。',related:['xiantian-bagua','qian-trigram','kun-trigram']},
  {slug:'bagua-wangxiangxiuqiusi',name:'八卦旺相休囚死',pinyin:'Bā Guà Wàng Xiàng Xiū Qiú Sǐ',english:'Five Seasonal States of Trigrams',category:'yijing',shortDesc:'八卦各随季节五行轮转的旺相休囚死，断卦先看卦气之旺衰。',detail:'八卦旺相休囚死是把五行旺相休囚死的法则落实到卦上，以断卦之气的盛衰。八卦各配五行：乾兑属金、震巽属木、坎属水、离属火、坤艮属土。当令者旺：乾兑旺于秋，震巽旺于春，坎旺于冬，离旺于夏，坤艮旺于四季末月；令所生者为相，生令者为休，克令者为囚，令所克者为死，如春月震巽木旺、离火相、坎水休、坤艮土囚（一说坤艮亦受克）、乾兑金死。占筮断卦先察卦与用爻所值之月建得气与否，旺相者吉、休囚死者衰，此即京房卦气旺衰之说在断卦上的运用。',related:['qian-trigram','guaqi','yuejian-yao']},
  {slug:'tiandi-zhi-shu',name:'天地之数',pinyin:'Tiān Dì Zhī Shù',english:'Numbers of Heaven and Earth',category:'yijing',shortDesc:'天一地二至天九地十，天数二十五地数三十，合五十五，大衍所本。',detail:'天地之数出自《系辞传》：「天一，地二，天三，地四，天五，地六，天七，地八，天九，地十。」天数指一三五七九五个奇数，共二十五；地数指二四六八十五个偶数，共三十；天地之数合为五十有五，所谓「此所以成变化而行鬼神也」。天地之数即河图之数，五位相得而各有合，生数成数由此而立。大衍之数五十（一说五十有五取其整数），占筮起数皆本于天地之数，故学易先明奇偶生成之理。',related:['hetu','dayan-shifa','xici']},
  {slug:'wuxing-shengshu',name:'五行生成数',pinyin:'Wǔ Xíng Shēng Chéng Shù',english:'Generating-Completing Numbers of Five Elements',category:'yijing',shortDesc:'五行各配生数成数：水一六火二七木三八金四九土五十。',detail:'五行生成数是把一至十数分属五行的配数体系：水数一六（天一生水、地六成之），火数二七，木数三八，金数四九，土数五十。其中一二三四五为生数，主万物之始生；六七八九十为成数，主万物之完成，生数加中五即得成数。此说以河图为据，配五方五时：北方冬水、南方夏火、东方春木、西方秋金、中央四季土。术数中凡取五行之数（如择日河洛数、五行局数、卦数五行）皆源于此，故与河图之学相表里。',related:['hetu','hetuluoshu','bagua-wangxiangxiuqiusi']},
  // ===== 易学深化 · 京房易学体系 (5) =====
  {slug:'jingshi-yixue',name:'京氏易学',pinyin:'Jīng Shì Yì Xué',english:'Jing Fang Yi Learning',category:'yijing',shortDesc:'汉代京房创立的占验易学：八宫、纳甲、世应、飞伏、六亲。',detail:'京氏易学指西汉京房（京君明）所传的象数易学体系，是汉代象数易的代表，也是六爻纳甲筮法的源头。京房受易于焦延寿，把《周易》六十四卦按八宫排列（乾坎艮震巽离坤兑八宫，每宫八卦），创立八宫卦序、纳甲（卦爻纳干支）、世应、飞伏、建候积算诸法，又以五行生克论卦爻，配六亲、六神，使卦爻与干支历法、五行生克贯通，形成一套可操作的占验系统，著《京氏易传》。后世以钱代蓍的纳甲筮法（六爻）即直接承自京氏易学。',related:['najia','bagong','yaochen','guaqi']},
  {slug:'najia-jiangong',name:'纳甲',pinyin:'Nà Jiǎ',english:'Najia (Embedding Heavenly Stems)',category:'yijing',shortDesc:'京房以八宫卦配十干，使卦爻各得干支五行的系统。',detail:'纳甲是京房易学的核心技法：把天干地支配入八卦六爻，使抽象的卦爻获得干支与五行属性。京房纳甲的口诀为乾纳甲壬（内卦纳甲、外卦纳壬）、坤纳乙癸、震纳庚、巽纳辛、坎纳戊、离纳己、艮纳丙、兑纳丁，再各配地支（乾内卦子寅辰、外卦午申戌等），爻位五行由此而定。有了干支五行，方能论生克、装六亲、配六神，故纳甲是六爻装卦与断卦的底层框架；其原理与《参同契》月体纳甲之说相通，后世合而研究之。',related:['jingshi-yixue','yueti-najia','liuyao']},
  {slug:'yueti-najia',name:'月体纳甲',pinyin:'Yuè Tǐ Nà Jiǎ',english:'Lunar-Phase Najia',category:'yijing',shortDesc:'《参同契》以月相盈亏配八卦方位与天干，为纳甲本义。',detail:'月体纳甲是《周易参同契》借月相盈亏说明纳甲原理的学说。月初三新月见于西方庚位，配震卦纳庚；初八上弦月见于南方丁位，配兑卦纳丁；十五满月见于东方甲位，配乾卦纳甲；十六月始亏，巽纳辛；二十三下弦月见于南方丙位，艮纳丙；三十晦月，配坤纳乙癸。八卦方位恰合月行轨迹，故纳甲本取月体纳甲之义，象征阴阳消息盈亏之象。京房纳甲又赋予卦爻干支，用于占筮，两说同源异流，均为易学象数的重要部分。',related:['cantongqi','najia','jingshi-yixue']},
  {slug:'yaochen',name:'爻辰',pinyin:'Yáo Chén',english:'Line Earthly Branches (Yao Chen)',category:'yijing',shortDesc:'郑玄以乾坤十二爻配十二辰月与二十八宿解经之例。',detail:'爻辰是东汉郑玄创立的易例，以卦爻配十二辰（地支月）来解说卦爻辞。其法以乾坤两卦十二爻配十二月：乾卦初九至九五纳子寅辰午申戌，上九纳戌而乾通阳；坤卦初六至六五纳未酉亥丑卯巳，上六纳巳，乾坤十二爻恰配一周十二辰，并与十二律吕、二十八宿相值。如乾初九爻辞「潜龙勿用」，郑玄以初九值子月（十一月），阳气潜藏地下释之。爻辰说把卦爻置于历法星象之中，是汉易以象数解经的代表性体例，与纳甲同为爻配干支之学的两支。',related:['jingshi-yixue','najia','wenyan-zhuan']},
  {slug:'guabian',name:'卦变',pinyin:'Guà Biàn',english:'Hexagram Transformation Theory',category:'yijing',shortDesc:'以一卦阴阳爻推移变化成他卦之说，虞翻、李之才各有卦变图。',detail:'卦变是象数易学解说卦爻辞来源的重要体例，指六十四卦之间由阴阳爻位置推移而相互转化，如复卦初阳上进而成临、泰诸卦。汉代虞翻以十二消息卦为纲，谓某卦自某消息卦变来（如讼卦自遁卦变来），用以解释卦辞爻辞的取象；宋代李之才作《变卦反对图》《六十四卦相生图》，程颐《易传》亦以卦变说义理。卦变不同于占筮所得之变卦（之卦）：卦变是卦与卦之间的体例推演，属解经工具，观察爻的往来升降可知一卦之义理，为历代易家所重。',related:['zhigua','xiaoxi-gua','hugua']},
  // ===== 易学深化 · 卦爻结构与爻位 (5) =====
  {slug:'chengcheng-biying',name:'承乘比应',pinyin:'Chéng Chéng Bǐ Yìng',english:'Supporting, Riding, Neighboring, Responding',category:'yijing',shortDesc:'爻与爻的四种关系：阴承阳、阴乘阳、相邻相比、同位相应。',detail:'承乘比应是分析一卦六爻相互关系的四种体例。承指下爻承托上爻，阴爻承阳爻为顺承，如初六承九二、六二承九三；乘指上爻凌驾下爻，阴爻乘阳爻为逆乘，主不安，如六四乘九三；比指相邻两爻相比相亲，如初与二、二与三皆比；应指上下卦同位爻相应，初与四、二与五、三与上相呼应，阴阳相应为有应，同气相敌为无应。爻辞吉凶每系于此四者：得承得应者多吉，失比被乘者多凶，二五居中相应尤为美善。',related:['yaowei-shuo','guazhu','xici']},
  {slug:'yaowei-shuo',name:'爻位说',pinyin:'Yáo Wèi Shuō',english:'Doctrine of Line Positions',category:'yijing',shortDesc:'系辞爻位之论：初难知上易知，二多誉四多惧三多凶五多功。',detail:'爻位说是《系辞传》总结六爻位置吉凶的学说。六爻自下而上各有其位之义：初爻为事之始，隐微难知；上爻为事之终，已成易知，故谓「其初难知，其上易知」。中间四爻，《系辞》曰「二与四同功而异位，其善不同：二多誉，四多惧」「三与五同功而异位：三多凶，五多功」，盖二居内卦之中得中位故多誉，四近君位多惧，三居下卦之极多凶，五居尊位得中故多功。爻位说又讲当位不当位：阳爻居奇位、阴爻居偶位为得正，反之失正；居中得正为「中正」，最为美善。断爻先察时位，此系辞观爻之要义。',related:['guazhu','chengcheng-biying','xici']},
  {slug:'guazhu',name:'卦主',pinyin:'Guà Zhǔ',english:'Ruling Line of a Hexagram',category:'yijing',shortDesc:'一卦之主爻：或为成卦之主，或为主卦之主，统摄全卦之义。',detail:'卦主是一卦之中统摄全卦意义的主爻。每卦六爻，未必等量齐观，总有某爻为一卦之枢机。卦主分两类：成卦之主，指卦之所以成为此卦的关键一爻，如夬卦上六、剥卦上九之类，一爻当位而五阳从之；主卦之主，指卦德最好的中正之爻，多为九五或六二，如乾卦九五「飞龙在天」即主卦之主，比卦九五以刚中为众阴所比。读卦先寻卦主：卦主得位得时，全卦之德便有着落；观爻辞亦以卦主为准绳，与卦时、爻位之说相表里。',related:['yaowei-shuo','chengcheng-biying','guaci']},
  {slug:'liangyi',name:'两仪',pinyin:'Liǎng Yí',english:'Two Modes (Yin and Yang)',category:'yijing',shortDesc:'太极所生之阴阳，两仪即阴阳，为万物化生之两端。',detail:'两仪出自《系辞传》「易有太极，是生两仪」，指太极分化而出的阴阳二气。两仪可以是天地、阴阳、奇偶、刚柔、动静等一切相对相待的两端；就画卦而言，阳爻（—）与阴爻（--）即两仪之象，八卦六十四卦皆由两仪推演而成。两仪并非判然对立，而是互根互涵、此消彼长，故又有「两仪生四象」之展：阴阳再各分老少，成太阳少阴少阳太阴四象。两仪观念贯穿易学，一阴一阳之谓道即两仪运行之道。',related:['taiji','sixiang','yinyang']},
  {slug:'sixiang',name:'四象',pinyin:'Sì Xiàng',english:'Four Images (Old-Young Yin-Yang)',category:'yijing',shortDesc:'阴阳各分老少为四象：老阳少阳老阴少阴，即揲蓍所得七八九六。',detail:'四象在易学中有两义：一为宇宙生成层，《系辞》「太极生两仪，两仪生四象，四象生八卦」，指阴阳再分阴阳而成老阳、少阴、少阳、老阴四象，春夏秋冬四时即四象之行；二为占筮层，大衍揲蓍每爻所得之数正应四象：九为老阳（动爻，阳变阴），七为少阳（静），六为老阴（动，阴变阳），八为少阴（静），故「七八不变，九六变」，六爻老阳老阴发动变化即由四象而来。四象之说沟通宇宙论与筮法，是学易的基本概念。',related:['liangyi','jiuliu','dayan-shifa']},
  // ===== 易学深化 · 八卦万物类象 (8) =====
  {slug:'qian-leixiang',name:'乾卦类象',pinyin:'Qián Guà Lèi Xiàng',english:'Qian Trigram Analogies',category:'yijing',shortDesc:'乾为天为君为父为马为金为首，纯阳至刚，主刚健。',detail:'乾卦三爻皆阳，其性至刚至健，动而不息，为天、为圜、为君、为父、为玉、为金、为寒、为冰、为大赤、为良马、为老马、为瘠马、为驳马、为木果，其于人也为头为首为骨。观物取象：天象为日、晴、雷电之威；人伦为君上、父亲、丈夫、长者、官贵；动物为马、龙、狮、象等刚健之兽；器物为金玉珠宝、钟鼎、圆形之物、车辆冠冕；人事主刚健、进取、权威、决断、政府、圆满；疾病主头面骨脑。类象之旨，触类而长，凡至刚至动、圆满贵重者皆可归乾，故说卦以乾为首而推之无穷。',related:['qian-trigram','shuogua','kun-leixiang']},
  {slug:'kun-leixiang',name:'坤卦类象',pinyin:'Kūn Guà Lèi Xiàng',english:'Kun Trigram Analogies',category:'yijing',shortDesc:'坤为地为母为布为牛为大舆，纯阴至顺，主柔顺包容。',detail:'坤卦三爻皆阴，其性至顺至柔，厚德载物，为地、为母、为布、为釜、为吝啬、为均、为子母牛、为大舆、为文、为众、为柄，其于地也为黑。观物取象：天象为云、阴、土、雾；人伦为母、妻、臣民、众人、乡里；动物为牛、牝马；器物为方物、土器、布帛、车舆、仓库；人事主柔顺、包容、承载、收藏、养育、勤俭、平正、群众；疾病主腹脾胃。凡至柔至顺、方正包容、承载万物者皆属坤，与乾之刚健相对而相成，故乾坤并称易之门。',related:['kun-trigram','shuogua','qian-leixiang']},
  {slug:'zhen-leixiang',name:'震卦类象',pinyin:'Zhèn Guà Lèi Xiàng',english:'Zhen Trigram Analogies',category:'yijing',shortDesc:'震为雷为龙为长子为足，一阳初动，主震动奋发。',detail:'震卦一阳在下、二阴在上，其性动，为雷、为龙、为玄黄、为旉（花）、为大涂（大道）、为长子、为决躁、为苍筤竹、为萑苇，其于马也为善鸣、为馵足、为作足、为的颡，其于稼也为反生，其究为健、为蕃鲜。观物取象：天象为雷、地震、春发；人伦为长子、壮男、将帅；动物为龙、蛇、马之善鸣者；人事主动、惊、起、发愤、震怒、迁徙、新生；疾病主足肝惊风。凡奋起震动、由静而动者皆属震，如惊雷破蛰、万物萌生之象。',related:['zhen-trigram','shuogua','xun-leixiang']},
  {slug:'xun-leixiang',name:'巽卦类象',pinyin:'Xùn Guà Lèi Xiàng',english:'Xun Trigram Analogies',category:'yijing',shortDesc:'巽为风为木为长女为鸡为股，一阴入二阳，主顺入渗透。',detail:'巽卦一阴在下、二阳在上，其性入，为风、为木、为长女、为绳直、为工、为白、为长、为高、为进退、为不果、为臭，其于人也为寡发、为广颡、为多白眼，为近利市三倍，其究为躁卦。观物取象：天象为风、气、云散；人伦为长女、寡妇、商贾、工匠；动物为鸡、飞禽；器物为绳、木器、扇、帆、文书；人事主顺、入、谦逊、渗透、传播、反复不定、谋利；疾病主股肱风疾。凡无孔不入、柔顺潜入、随风而动者皆属巽，所谓「随风巽，君子以申命行事」。',related:['xun-trigram','shuogua','zhen-leixiang']},
  {slug:'kan-leixiang',name:'坎卦类象',pinyin:'Kǎn Guà Lèi Xiàng',english:'Kan Trigram Analogies',category:'yijing',shortDesc:'坎为水为月为盗为中男为耳，一阳陷二阴，主险陷智谋。',detail:'坎卦一阳陷于二阴之中，其性险陷，为水、为沟渎、为隐伏、为矫輮、为弓轮，其于人也为加忧、为心病、为耳痛、为血卦、为赤，其于马也为美脊、为亟心、为下首、为薄蹄、为曳，其于舆也为多眚、为通、为月、为盗，其于木也为坚多心。观物取象：天象为月、雨、雪、江河湖海；人伦为中男、智谋之士、盗贼、劳苦之人；动物为猪、鱼、狐；器物为舟车、轮、弓、井、泉；人事主险、陷、劳、通、智、隐伏、流动；疾病主耳肾血。凡外柔内刚、险中藏智、流动不居者皆属坎，习坎有孚，险中求通之义。',related:['kan-trigram','shuogua','li-leixiang']},
  {slug:'li-leixiang',name:'离卦类象',pinyin:'Lí Guà Lèi Xiàng',english:'Li Trigram Analogies',category:'yijing',shortDesc:'离为火为日为电为中女为雉为目，一阴附二阳，主光明附丽。',detail:'离卦一阴附于二阳之间，其性丽（附丽、明丽），为火、为日、为电、为中女、为甲胄、为戈兵，其于人也为大腹，为乾卦、为鳖、为蟹、为蠃、为蚌、为龟，其于木也为科上槁。观物取象：天象为日、电、晴明、火光；人伦为中女、文士、目明之人；动物为雉、龟、蚌蟹；器物为灯烛、文书、甲骨、戈兵、网络；人事主明、丽、文明、文采、依附、警觉、分离；疾病主目心火。凡光明炽盛、文明相附、外强中干者皆属离，如日月丽天、百谷草木丽土之象。',related:['li-trigram','shuogua','kan-leixiang']},
  {slug:'gen-leixiang',name:'艮卦类象',pinyin:'Gèn Guà Lèi Xiàng',english:'Gen Trigram Analogies',category:'yijing',shortDesc:'艮为山为径路为少男为狗为手，一阳在上，主静止安止。',detail:'艮卦一阳在上、二阴在下，其性止，为山、为径路、为小石、为门阙、为果蓏、为阍寺、为指、为狗、为鼠、为黔喙之属，其于木也为坚多节。观物取象：天象为山、石、云雾笼峰；人伦为少男、童子、守门人、隐士；动物为狗、鼠、虎豹；器物为门阙、石、高台、阶梯、丘坟；人事主止、静、阻、守、成终、坚忍、笃实；疾病主手背骨节。凡静止如山、止其所当止、高耸阻隔者皆属艮，所谓「艮，止也，时止则止，时行则行」。',related:['gen-trigram','shuogua','dui-leixiang']},
  {slug:'dui-leixiang',name:'兑卦类象',pinyin:'Duì Guà Lèi Xiàng',english:'Dui Trigram Analogies',category:'yijing',shortDesc:'兑为泽为少女为巫为口舌为羊，一阴在上，主喜悦言说。',detail:'兑卦一阴在上、二阳在下，其性说（喜悦），为泽、为少女、为巫、为口舌、为毁折、为附决，其于地也为刚卤、为妾、为羊。观物取象：天象为泽、露、雨润；人伦为少女、妾、巫师、口才之士；动物为羊、泽中鱼介；器物为泽池、杯盘、乐器、口舌之器；人事主悦、言、讲学、交易、饮食、口舌是非、毁折；疾病主口舌肺金。凡和悦动人、以言相说、滋润万物者皆属兑；兑又主口，故言谈辩说、朋友讲习皆取兑象，「丽泽兑，君子以朋友讲习」。',related:['dui-trigram','shuogua','gen-leixiang']},
  // ===== 易学深化 · 流派典籍 (7) =====
  {slug:'xiangshu-pai',name:'象数派',pinyin:'Xiàng Shù Pài',english:'Image-Number School',category:'yijing',shortDesc:'以卦象与数理说易之派：汉易卦气纳甲爻辰与宋图书之学。',detail:'象数派是与义理派相对的易学流派，主张以卦爻之象（卦象、爻象、物象）与数（阴阳奇偶之数、河洛之数、卦气历数）解说《周易》。汉代的孟喜、京房以卦气、纳甲说易，郑玄主爻辰，荀爽虞翻重卦变、互体、旁通与逸象，皆属汉易象数之学；宋代图书之学以河图洛书、先天图、太极图为说，邵雍以数推演宇宙，朱熹亦主「易本卜筮之书」而兼采象数。象数派为占筮与术数提供了直接的理论基础，六爻、梅花、奇门等皆其流裔。',related:['guaqi','yaochen','jingshi-yixue']},
  {slug:'yili-pai',name:'义理派',pinyin:'Yì Lǐ Pài',english:'Meaning-Principle School',category:'yijing',shortDesc:'以阴阳刚柔之道与人事义理解易之派，王弼程颐为代表。',detail:'义理派是与象数派相对的易学流派，主张透过卦爻辞阐发天地阴阳之理与修齐治平之义，不重占筮取象。三国魏王弼扫除汉易象数，以老庄玄理注易，开义理一派；宋代程颐著《程氏易传》专以儒家人事义理说易，为义理派集大成之作；胡瑗、欧阳修、张载等亦各有阐发。义理派发挥「一阴一阳之谓道」「自强不息」「厚德载物」等思想，把《周易》从卜筮之书提升为穷理尽性至命之学，深刻影响宋明理学。两派同源而异趋，一重观象玩辞、一重明理致用，后世多主张象数与义理并重。',related:['xiangshu-pai','liangpai-liuzong','xici']},
  {slug:'liangpai-liuzong',name:'两派六宗',pinyin:'Liǎng Pài Liù Zōng',english:'Two Schools and Six Sects',category:'yijing',shortDesc:'四库馆臣归纳易学源流：象数义理两派，占筮等六宗。',detail:'两派六宗是《四库全书总目》对易学流派的经典概括：「易之为书，推天道以明人事者也」，《左传》所记诸占，犹是卜筮之遗；至汉象数之学兴，京房焦延寿之徒以占候为说；魏王弼始黜象数、阐义理，宋儒益衍其绪。四库馆臣因以两派（象数、义理）六宗（占筮、禨祥、造化、老庄、儒理、史事）总括历代易学：占筮宗本《左传》，禨祥宗本京焦，造化宗本陈邵，老庄宗本王弼，儒理宗本胡程，史事宗本李光杨万里。两派六宗之说出而后世易学源流一目了然，为治易者入门之津梁。',related:['xiangshu-pai','yili-pai','jingshi-yixue']},
  {slug:'yixiang-yi',name:'逸象',pinyin:'Yì Xiàng',english:'Extended Analogies (Yi Xiang)',category:'yijing',shortDesc:'说卦所无而各家补出的卦象，荀九家与虞翻逸象最著。',detail:'逸象指《说卦传》八卦取象之外，各家经师补充发明的新卦象。汉代解易者以为说卦取象不足尽卦爻之义，遂广引物象以释经，其中荀爽等九家集注所载称「九家逸象」，如乾为龙、为直、为衣、为言之类；三国虞翻治孟氏易，逸象最多，有「虞氏逸象」之称，多达数百条，如乾为王、坤为臣、震为侯、坎为孚之类。逸象大大扩充了八卦类象的体系，使取象解经更为细密，然亦因各家异说纷纭而致牵强附会，后世治汉易者每据辑佚书考稽之。',related:['shuogua','guabian','xiangshu-pai']},
  {slug:'yilin',name:'焦氏易林',pinyin:'Jiāo Shì Yì Lín',english:'Jiao Shi Yi Lin',category:'yijing',shortDesc:'焦延寿以六十四卦互变四千零九十六卦，各系四言林辞。',detail:'焦氏易林旧题西汉焦延寿（焦赣）撰，是汉代占筮易的鸿篇巨制。其法以一卦之变尽六十四卦，六十四卦共得四千零九十六卦变，每变各系一首以四言韵语写成的占辞（林辞），总四言诗四千余首，文辞古雅，内容广涉人事吉凶、征伐、婚姻、田猎、灾异。易林所本为焦氏之卦变法（本卦变之卦、互卦参断），与京房八宫纳甲同为汉易占验的两大系统。易林文辞富赡，兼具占书与文学价值，清代学者多有整理辑注，于易学、训诂、文学研究皆极珍贵。',related:['jingshi-yixue','guabian','dayan-shifa']},
  {slug:'shiyi',name:'十翼',pinyin:'Shí Yì',english:'Ten Wings',category:'yijing',shortDesc:'解释经文的七种十篇传文：彖象系辞文言说卦序卦杂卦。',detail:'十翼是《易传》的别名，指解释《周易》经文（卦辞爻辞）的十篇传文，相传为孔子及其门人所撰，取辅翼经文之义故名十翼。十翼共七种十篇：彖传上下、象传上下（大象小象）、系辞传上下、文言传、说卦传、序卦传、杂卦传。彖传释卦辞、象传释卦象与爻辞，系辞为易道通论，文言专释乾坤二卦，说卦论八卦取象方位，序卦说六十四卦次序之理，杂卦以对举方式点明各卦要义。经有十翼而后义理大明，故易学传统重传解经，先读十翼再研经文为治易正途。',related:['tuanci','xici','wenyan-zhuan']},
  {slug:'wenyan-zhuan',name:'文言传',pinyin:'Wén Yán Zhuàn',english:'Commentary on the Words of Qian and Kun',category:'yijing',shortDesc:'十翼之一，专释乾坤二卦卦爻辞，多引子曰，阐四德。',detail:'文言传是十翼之一，取文饰卦下之言以明义之意，专释乾、坤两卦的卦辞与爻辞，是十翼中唯一不逐卦而作、仅详于乾坤的传文。文言发挥「元亨利贞」为仁礼义智四德，释乾卦各爻辞，如解「潜龙勿用」为「龙德而隐者也」，提出「君子以成德为行」「知进退存亡而不失其正者，其唯圣人乎」等名论；释坤卦则言「直方大」「敬义立而德不孤」及「积善之家必有余庆，积不善之家必有余殃」。文言辞旨精深，多引「子曰」，是理解乾坤两卦义理与儒家道德哲学的枢纽篇章。',related:['shiyi','qian-trigram','kun-trigram']},
  // ===== 易学深化 · 占筮与断辞 (10) =====
  {slug:'dayan-shifa',name:'大衍筮法',pinyin:'Dà Yǎn Shì Fǎ',english:'Great Expansion Divination Method',category:'yijing',shortDesc:'系辞所载蓍草占法：大衍之数五十其用四十有九，三变成爻。',detail:'大衍筮法出自《系辞传》：「大衍之数五十，其用四十有九。分而为二以象两，挂一以象三，揲之以四以象四时，归奇于扐以象闰。」其法取蓍草五十茎，虚一不用；任意分二，挂一于指间，四四数之，归余于扐，此为一变；三变之后得六七八九之数定一爻，老阳九、老阴六为动爻，少阳七、少阴八为静爻；十八变而成六爻之卦，再观本卦、之卦与变爻以断吉凶。大衍筮法是《周易》最古老的成卦之法，后为以钱代蓍的金钱卦所承。',related:['sixiang','jiuliu','bianzhan-qili']},
  {slug:'bianzhan-qili',name:'变占七例',pinyin:'Biàn Zhàn Qī Lì',english:'Seven Cases of Changed-Line Divination',category:'yijing',shortDesc:'朱熹据春秋筮例归纳的断卦通则：视动爻多少取辞。',detail:'变占七例是朱熹《易学启蒙》总结的先秦断卦通则，按本卦动爻（变爻）多少取卦辞爻辞为断：六爻皆不变，以本卦卦辞占；一爻变，以本卦变爻爻辞占；二爻变，以本卦二变爻爻辞占，以上一爻（上爻）为主；三爻变，占本卦与之卦卦辞，以本卦为贞、之卦为悔；四爻变，以之卦二不变爻爻辞占，以下爻为主；五爻变，以之卦不变爻爻辞占；六爻皆变，乾、坤二卦占用九用六，其余以之卦卦辞占。七例使动爻占断有了统一法则，为后世占筮者所宗。',related:['dayan-shifa','zhigua','guaci']},
  {slug:'jiuliu',name:'九六',pinyin:'Jiǔ Liù',english:'Nine and Six (Yang-Yin Line Titles)',category:'yijing',shortDesc:'易爻阳称九阴称六：九为老阳六为老阴，七八不变九六变。',detail:'九六是《周易》称爻的体例：阳爻称九、阴爻称六，如乾卦自下而上为初九、九二……上九，坤卦为初六、六二……上六。其所以称九六而不称七八，因占筮所得老阳之数为九、老阴之数为六，九六为变爻，系辞系于变爻之上以见占断之要，所谓「爻者言乎变者也」；七八为少阳少阴，不变，故不以之称爻。六十四卦三百八十四爻，阳爻皆称九、阴爻皆称六，乾坤二卦又别附「用九」「用六」以总六爻纯阳纯阴之用。',related:['sixiang','dayan-shifa','yaoti']},
  {slug:'yaoti',name:'爻题',pinyin:'Yáo Tí',english:'Line Titles (Chu Jiu, Liu Er...)',category:'yijing',shortDesc:'每爻的称谓体例：初九初六、九二六二至上九上六。',detail:'爻题是《周易》每卦六爻的固定称谓。爻位自下而上为初、二、三、四、五、上，六爻中阳爻称九、阴爻称六，爻题即由位名与阴阳之称合成：如乾卦自下而上依次为初九、九二、九三、九四、九五、上九，坤卦为初六、六二、六三、六四、六五、上六，其余六十二卦仿此。初与上称初称上而不称一二六，取初言始、上言终之义。爻题使每爻有了确定的代号，卦辞爻辞皆赖此编次，读易、占筮、引卦必先识爻题。',related:['jiuliu','yaoci','sixiang']},
  {slug:'yuanheng-lizhen',name:'元亨利贞',pinyin:'Yuán Hēng Lì Zhēn',english:'Yuan, Heng, Li, Zhen (Four Virtues)',category:'yijing',shortDesc:'乾卦卦辞，易占断辞之首：大通而利于守正，后衍为四德。',detail:'元亨利贞是乾卦卦辞，也是《周易》最著名的断辞。本义以元为大、亨为通、利为宜、贞为正固，谓天道乾健，大通而利于守正；《文言传》则推为四德：元者善之长（仁）、亨者嘉之会（礼）、利者义之和（义）、贞者事之干（智），配春夏秋冬、东南西北。元亨利贞分言之各为一德，合言之即乾道之全；他卦卦辞亦多系此四字而各有损益（如屯卦「元亨利贞」、坤卦「元亨，利牝马之贞」），故训诂卦辞必先知四字之义。',related:['wenyan-zhuan','guaci','qian-trigram']},
  {slug:'jixiong-huilin',name:'吉凶悔吝',pinyin:'Jí Xiōng Huǐ Lìn',english:'Auspicious, Ominous, Regret, Pity (Judgment Words)',category:'yijing',shortDesc:'卦爻辞断语体系：吉凶悔吝厉咎无咎各有所主。',detail:'吉凶悔吝是《周易》占断语的核心。《系辞》曰「吉凶者，失得之象也」「悔吝者，忧虞之象也」：吉为得、凶为失；悔为过而知改，趋向于吉；吝为知过不改、陷于忧惜，趋向于凶，故谓「悔吝者，言乎其小疵也」。「厉」为危殆，「咎」为灾患，凡言「厉」者戒其危，言「咎」者示其过；「无咎」为善补过，乃《易》最重之词——有咎能补则无咎，故「无咎者，善补过也」。吉凶断人事之成毁，悔吝厉咎示趋避之几微，此易教「惧以终始」之所在。',related:['guaci','xici','yuanheng-lizhen']},
  {slug:'sanyi',name:'三易',pinyin:'Sān Yì',english:'Three Yi (Lianshan, Guicang, Zhouyi)',category:'yijing',shortDesc:'夏商周三代之易：连山、归藏、周易，皆以八卦重叠六十四卦。',detail:'三易指传说中夏、商、周三代的三种易书，合称三易。《周礼》春官掌「三易之法：一曰连山，二曰归藏，三曰周易」，郑玄谓连山为夏易、归藏为商易、周易为周代之易，三者皆八经卦重为六十四卦，惟卦序取义不同：连山以艮卦为首，象山之出云连绵，故云连山；归藏以坤卦为首，主万物莫不归藏于地；周易以乾卦为首，首乾次坤。连山归藏后世亡佚，仅于辑佚与王家台秦简《归藏》残文可见其概，今存者唯周易，然三易之名揭示了易学源远流长的传承。',related:['liushisi-gua','qian-trigram','kun-trigram']},
  {slug:'zhenhui',name:'贞悔',pinyin:'Zhēn Huǐ',english:'Zhen and Hui (Inner and Outer Trigram)',category:'yijing',shortDesc:'占筮体例：内卦曰贞、外卦曰悔，贞我悔彼、贞静悔动。',detail:'贞悔是先秦占筮术语，指一卦上下两体的称谓。《左传》《国语》筮例中，筮者以本卦的内卦（下卦）为贞、外卦（上卦）为悔：贞主事之始、主我方，悔主事之终、主对方，故谓「贞我悔彼」。又贞有正固之义，主静；悔有变动之义，主动，所谓「贞为事之始，悔为事之终」。三爻皆变或卦变之时，常以本卦为贞、之卦为悔参断（如「遇观之否」「艮之八」等例）。贞悔之说为理解春秋筮例与卦变占断之钥匙。',related:['chunqiu-shili','bianzhan-qili','zhigua']},
  {slug:'chunqiu-shili',name:'春秋筮例',pinyin:'Chūn Qiū Shì Lì',english:'Chunqiu Divination Cases',category:'yijing',shortDesc:'左传国语所载占筮实例，古筮法断卦之直接史料。',detail:'春秋筮例指《左传》《国语》中保存的先秦占筮实例，是研究古筮法最珍贵的史料。著名筮例有：庄公二十二年周史筮陈敬仲「遇观之否」，以观卦六四爻辞「观国之光，利用宾于王」断其子孙有国；闵公元年毕万筮仕于晋「遇屯之比」，以屯卦初九变爻辞断其昌；襄公九年穆姜筮「遇艮之八」，史官以其五爻变唯六二不变称之；僖公十五年秦伯伐晋筮「遇蛊」，卜徒父以卦象断吉。诸例显示先秦占断：一爻变者取变爻辞，多爻变者以本卦之卦参断，兼取卦象卦名，与后世朱子变占七例若合符节。',related:['zhenhui','bianzhan-qili','zhigua']},
  {slug:'yiyou-sanyi',name:'易有三义',pinyin:'Yì Yǒu Sān Yì',english:'Three Meanings of Yi',category:'yijing',shortDesc:'易纬之说：易一名而含三义，简易、变易、不易。',detail:'易有三义出自《易纬·乾凿度》：「易一名而含三义，所谓易也，变易也，不易也。」郑玄《易赞》承之而备言其目：易简一也——乾以易知、坤以简能，易简而天下之理得；变易二也——阴阳往来、四时更迭，卦爻变动不居；不易三也——天地之位、尊卑之序、名分之常，终古不变。三义中简易言其道之要，变易言其体之用，不易言其理之常，合之乃见易道之全。后世论易体用，多以此三义为纲，与「周流六虚、变动不居」之说相发明。',related:['xici','yiwei','liangpai-liuzong']},
  // ===== 易学深化 · 卦序与卦义 (8) =====
  {slug:'liuri-qifen',name:'六日七分',pinyin:'Liù Rì Qī Fēn',english:'Six Days Seven Parts (Hexagram Qi)',category:'yijing',shortDesc:'孟喜卦气值日法：四正卦主四时，余六十卦每卦值六日七分。',detail:'六日七分是汉代孟喜卦气说的值日法则。其法以坎、离、震、兑四正卦（四方之卦）各主一季，二十四爻分主二十四节气，不入值日；其余六十卦配一年三百六十五又四分之一日，均分之每卦当值六日七分（古历一日八十分），故称六日七分。六十卦依十二消息卦为纲轮值，辟卦当十二月中气，每爻又应一候，与七十二候相配。京房承之创「建候积算」以推灾异吉凶应期。六日七分使卦爻与历数完全合一，为卦气学说的数理骨架，后世卦气图皆祖述于此。',related:['guaqi','xiaoxi-gua','qishier-hou']},
  {slug:'feifu-jibian',name:'非覆即变',pinyin:'Fēi Fù Jí Biàn',english:'Either Inverted or Changed (Hexagram Pairs)',category:'yijing',shortDesc:'六十四卦两两相偶的体例：或上下颠倒为对，或阴阳全变为对。',detail:'非覆即变是《周易》六十四卦编排的著名体例，出自孔颖达《周易正义》论卦序：六十四卦两两相偶，「非覆即变」。覆指把一卦上下颠倒（即综卦），如屯蒙、需讼、师比皆相覆为对，此类占大多数；但乾、坤、坎、离、颐、大过、中孚、小过八卦上下颠倒而卦不变，则改以阴阳全变（即错卦）相偶：乾与坤、坎与离、颐与大过、中孚与小过。故六十四卦共三十二对，或覆或变，两两相对而成序。此体例体现相反相成、相综相错之义，观卦序之妙必先知非覆即变。',related:['zonggua','cuogua','xugua']},
  {slug:'fangyuan-tu',name:'六十四卦方圆图',pinyin:'Liù Shí Sì Guà Fāng Yuán Tú',english:'Sixty-Four Hexagrams Square-Circle Diagram',category:'yijing',shortDesc:'邵雍先天图：内方外圆列六十四卦，圆图象天方图象地。',detail:'六十四卦方圆图又称伏羲六十四卦方位图，是邵雍《皇极经世》所传的先天易图。其图内为方图、外为圆图：圆图列六十四卦于圆周，自乾卦起左行，象天运转于外、日月星辰之运行，主流行；方图六十四卦纵横排列，自西北乾位向东南坤位展开，象地之方正、万物之定位，主对待。圆方相合，即「天地定位」加一倍法推衍六十四卦之全貌。此图把六十四卦的生成次序、阴阳消长与方位历数打成一片，为先天易学的代表图式，朱熹《周易本义》冠于书首。',related:['xiantian-bagua','qian-yongjiu']},
  {slug:'qian-yongjiu',name:'乾用九',pinyin:'Qián Yòng Jiǔ',english:'Yong Jiu of Qian',category:'yijing',shortDesc:'乾卦用九「见群龙无首吉」，六爻皆变时之断辞。',detail:'乾用九是《周易》乾卦特有的断辞：「用九，见群龙无首，吉。」坤卦则附「用六，利永贞」。六十四卦唯乾坤二卦有之，盖纯阳纯阴之卦六爻齐动时，卦辞不足以断，故别系用九用六以尽其变。用九之义，谓六爻皆阳而变，如群龙并现而无首可争，刚而能柔、不居其刚则吉，宋儒释为「乾元用九，乃见天则」；用六利永贞，则戒阴柔者永守其正。占筮得乾卦六爻皆动者，即以「见群龙无首吉」为断。',related:['jiuliu','bianzhan-qili','qian-trigram']},
  {slug:'fouji-tailai',name:'否极泰来',pinyin:'Fǒu Jí Tài Lái',english:'Extremity of Pi Yields Tai',category:'yijing',shortDesc:'否泰二卦相综之义：泰极则否、否极则泰，阴阳消长之必然。',detail:'否极泰来语出否泰二卦之义。泰卦地天泰，乾下坤上，天气上升、地气下降，阴阳交而万物通，主通泰；否卦天地否，坤下乾上，天气上腾、地气下沉，二气不交，主闭塞。十二消息卦中泰当正月三阳开泰，否当七月三阴浸长，然物极必反：泰至上六「城复于隍」而否将至，否至上九「倾否，先否后喜」而泰复来，故云否极泰来。此语既言世事循环、困极则亨之理，亦见《易》贵消息盈虚、与时偕行，处泰而思否、处否而望泰，为君子进退之大戒。',related:['xiaoxi-gua','boji-bifu','zonggua']},
  {slug:'jiji-weiji',name:'既济未济',pinyin:'Jì Jì Wèi Jì',english:'Ji Ji and Wei Ji (Completion and Incompletion)',category:'yijing',shortDesc:'易之终两卦：既济事已成，未济事未成，终以未济寓生生不息。',detail:'既济与未济是六十四卦的最后两卦，也是易道终始之义的集中体现。既济卦离下坎上，水火相交、各得其位，六爻皆当位，象事之已成，然其辞戒辞居多（初九「曳其轮」、上六「濡其首」），示成则易怠、盛极防衰；未济卦坎下离上，水火不交、六爻皆失位，象事之未成，然其卦辞「亨」，上九「有孚于饮酒，无咎」，示事虽未济而终可有为。以未济终篇而不以既济终篇，正寓易道「终则有始」、生生不息之义——成非究竟，未成乃化生之机。',related:['xugua','liushisi-gua']},
  {slug:'sunyi',name:'损益之道',pinyin:'Sǔn Yì Zhī Dào',english:'Way of Sun and Yi (Decrease and Increase)',category:'yijing',shortDesc:'损卦益卦之义：损下益上为损，损上益下为益，盈虚与偕行。',detail:'损益之道见乎损、益二卦。损卦山下有泽（损下益上），其象取损民以奉君，然损之极则上反受其损，故卦辞「损而有孚，元吉」；益卦风雷益（损上益下），其象取损君以惠民，民悦无疆，故「利有攸往，利涉大川」。彖传曰「损刚益柔有时，损益盈虚，与时偕行」，谓损之与益非一成不变，视时位而转。孔子读易至损益叹曰「自损者益，自益者损」，言人当谦虚自损、不可矜满，故《杂卦》云「损益，盛衰之始也」，君子观此知满招损谦受益之戒。',related:['zonggua','guabian','xici']},
  {slug:'boji-bifu',name:'剥极必复',pinyin:'Bō Jí Bì Fù',english:'Extremity of Bo Yields Fu',category:'yijing',shortDesc:'剥卦五阴剥一阳、复卦一阳来复，阳无可尽剥之理。',detail:'剥极必复言剥、复二卦消息之理。剥卦坤下艮上，五阴在下而一阳独存于上，如秋尽冬初万物剥落，阴气极盛；复卦震下坤上，一阳生于五阴之下，如冬至阳气潜回，故谓「复，其见天地之心乎」。消息卦中剥当九月、坤当十月、复当十一月冬至，五阴剥尽而一阳来复，可见阳刚之气生生不绝，虽剥至仅余一阳，终必复生，所谓「剥极必复」「阳无可尽之理」。此义既喻自然阴阳循环，又喻人事否塞困极之后必有生机，为易学「生生之谓易」的绝佳注脚。',related:['xiaoxi-gua','fouji-tailai','dongzhi']},
  // ===== 六爻深化 · 进阶判断 (16) =====
  {slug:'jinggua-liuyao',name:'静卦',pinyin:'Jìng Guà',english:'Static Hexagram (No Moving Lines)',category:'liuyao',shortDesc:'六爻皆静无动爻之卦，事无变动，专看用神旺衰与日月。',detail:'静卦指起卦所得六爻皆静、没有动爻的卦，与动卦相对。卦无动爻则事无变动之机、暂无变化之象，断法遂以用神为核心：看用神得月建日辰生扶与否，旺相临日月者，事虽缓而可成、根基已固；用神休囚、旬空、月破、入墓者，事难成就或需长久等待。静卦并非无事，而是事体尚未发动，宜守待时；若测久远之事得静卦而用神旺相，反主根基深厚、水到渠成。断静卦须细察日辰之力，静而旺相之爻亦有生克之权。',related:['yongshen-yao','richen','yuejian-yao']},
  {slug:'dujing',name:'独静',pinyin:'Dú Jìng',english:'Sole Static Line',category:'liuyao',shortDesc:'卦中五爻俱动仅一爻独静，独静之爻每为事之枢机。',detail:'独静与独发相对，指卦中五爻发动、唯余一爻安静的特殊卦象。群动之中唯此一爻不动，如乱局中一块定盘石，古人认为动静失衡之处正是事机所聚：断事之吉凶与应期，多系于独静之爻——独静之爻旺相临日月，主乱中有定、事有主心骨；独静之爻逢冲，则静被冲起，主事体被意外打破。应期之法：动多者以静爻值日应事，故断卦见独静，须格外留意此爻与日月用神的关系。',related:['dufaluandong','jinggua-liuyao','richen']},
  {slug:'ripo',name:'日破',pinyin:'Rì Pò',english:'Day Break (Line Broken by Day Branch)',category:'liuyao',shortDesc:'静爻被日辰所冲，旺相为暗动，休囚无气即为日破冲散。',detail:'日破与月破相对，指卦中静爻被日辰冲克而失力。日辰冲静爻，须分旺衰两途：爻旺相有气者，逢冲则动，是为暗动；爻休囚无气者，逢冲则散，其力尽失，是为日破（又称冲散）。用神日破，主所谋之事当日即散、望空而败；忌神日破，反主凶事消解。日辰之力只管当日，故日破之爻过此日，若得月建生扶或他日逢值，仍可转用，此为日破与月破（破及一月）不同之处。断卦须辨同是逢冲、旺暗动而衰日破。',related:['andong','yuepo-yao','richen']},
  {slug:'chongkong',name:'冲空',pinyin:'Chōng Kōng',english:'Void Line Clashed (Filling the Void)',category:'liuyao',shortDesc:'旬空之爻被冲则实，静空逢冲而起，主虚事转实、应期急促。',detail:'冲空指旬空之爻被日辰或动爻冲动的用法。旬空之爻虚而不实，最怕安静无用；一旦逢冲，空者被冲而实，静者被冲而动，如虚位忽得填塞，主所谋的虚事忽然成实、久候之事猝然发动，应期来得急促，故有「空爻逢冲，事急而应」之说。冲空应事之吉凶，看被冲之爻是喜是忌：用神逢冲空填实，主事情骤然落实、虚惊变喜；忌神逢冲空，则祸事猝发。断应期时，冲空之爻往往应在冲的当日或本旬之内。',related:['xunkong-yao','andong','yingqi']},
  {slug:'heban',name:'合绊',pinyin:'Hé Bàn',english:'Line Shackled by Combination',category:'liuyao',shortDesc:'用神动而逢合则被绊住，事迟难进，待冲开之日应事。',detail:'合绊指卦中用神（或世爻）发动而逢合，以致受绊不能行动。合我之神有三：日辰合之、他爻合之、变爻合之（动而化合）。用神动本主事有进展，一旦被合住，如骏马被绊、英雄被困，主事情阻滞迟延、欲进不能，或事成一半而悬而不决；应期须待冲开此合之日（逢冲则解），故断「合待冲」。若被合的是忌神，则反主其凶被绊、暂不为害。合起与合绊相对：静爻被日辰合起，主暗中有力、事被催动。',related:['richen','biangua','yingqi']},
  {slug:'hechu-fengchong',name:'合处逢冲',pinyin:'Hé Chù Féng Chōng',english:'Combination Met by Clash',category:'liuyao',shortDesc:'用神合而逢冲则事成复散；冲中逢合则先散后聚。',detail:'合处逢冲与冲中逢合是六爻断事反复的两条通则。用神动而化合，或与日月他爻成合，本主事情和合有成，若卦中又逢冲神冲散此合（日辰冲合、他爻冲合），便是合处逢冲：如婚约将成忽生变故、合作将定中途拆伙，主成而复散、好事多磨。反之，用神本被冲散，卦中又有合来解救，为冲中逢合：主先难后易、散而复聚、失而复得。断应期：合处逢冲应于冲日，冲中逢合应于合日，卦象反复处正是人事分合之机。',related:['heban','liuhegua','liuchonggua']},
  {slug:'jianyao',name:'间爻',pinyin:'Jiān Yáo',english:'Intermediate Lines (Between Shi and Ying)',category:'liuyao',shortDesc:'世应与世爻之间的爻位，主中间过程、阻隔与中介。',detail:'间爻指世爻与应爻之间所隔的两爻。六爻卦中世应各居其位（如世居初则应居四、世居二则应居五、世居三则应居六），其间上下相隔之二爻即为间爻。间爻象征世应之间的中间地带：测合作、交易、婚约，间爻代表中间人与中介过程；间爻旺相生合用神，主有人从中撮合、事得转圜；间爻临忌神发动或兄弟劫财，主中间阻隔、受人掣肘，事难直达；间爻旬空月破，则主中间环节虚悬无力。断世应之事，先察间爻动静，可定事之通达与迟滞。',related:['shiying','yongshen-yao','jishen-yao']},
  {slug:'zhenkong-jiakong',name:'真空假空',pinyin:'Zhēn Kōng Jiǎ Kōng',english:'True Void vs False Void',category:'liuyao',shortDesc:'旬空分真假：旺相发动之空为假空有用，休囚安静之空为真空。',detail:'真空假空是六爻精辨旬空用法的要诀。旬空之爻并非一律无用，须分真假：旺相之空、临日月之空、发动之空、受生之空，皆属假空（亦称动空化空、旺不为空），虽空而有用，出空、填实之时即能应事，故用神假空主谋事虚中藏实、先难后成；休囚无气之空、安静不动之空、墓绝之空，则为真空，如镜花水月，纵出空亦无根难用，用神真空主谋事成空、百无一实。断卦见空先辨旺衰动静，再论出空填实之应期，方不至见空即断凶。',related:['xunkong-yao','chongkong','yingqi']},
  {slug:'sanheju-liuyao',name:'三合局',pinyin:'Sān Hé Jú',english:'Three Harmony Combination (Liuyao)',category:'liuyao',shortDesc:'卦中三支合成申子辰等局，气势强盛，生克用神力倍。',detail:'六爻中的三合局指卦中地支合成申子辰水局、寅午戌火局、巳酉丑金局、亥卯未木局。成局之要有三：三支齐见而发动，或二爻动而日月临其一凑合成局，皆可论局。三合局成则三支一气、如结党成群，其力量远非单爻可比：合局生用神，主得众力之助、事势浩大必成；合局克用神，主众口铄金、事难挽回。局中缺一支者为半合局，力减一半；局成之后最忌被冲，冲则局散。测合伙、经营、婚姻等涉多方之事，尤重三合局之成破。',related:['liuqin','yongshen-yao','richen']},
  {slug:'zhugui-shangshen',name:'助鬼伤身',pinyin:'Zhù Guǐ Shāng Shēn',english:'Aiding the Officer to Harm the Self',category:'liuyao',shortDesc:'动爻生官鬼，鬼旺而克伤世身，主因助成祸、病势加重。',detail:'助鬼伤身是六爻的著名凶格：官鬼本为克世（身）之神，卦中又有动爻去生助官鬼，鬼得生而愈旺，反身克伤世爻，如纵虎伤人，谓之助鬼伤身。最常见的组合是妻财爻动而生官鬼，财动生鬼、鬼旺克身，主因财致祸、为利招灾；凡占病而财动生鬼，主病势转重、医药无功（因财又克父母爻之药）；占官非防刑狱加身。破解之法看子孙爻：子孙为制鬼之神，若卦中子孙旺动，可制鬼救身，凶中有救。',related:['choushen','jishen-yao','yongshen-yao']},
  {slug:'suigui-rumu',name:'随鬼入墓',pinyin:'Suí Guǐ Rù Mù',english:'Following the Officer into the Tomb',category:'liuyao',shortDesc:'世爻随官鬼同入墓库，主灾病困陷，占病讼出行最忌。',detail:'随鬼入墓是六爻断凶的经典组合，指世爻（自身）与官鬼一同陷入墓库。其象有二：世爻临官鬼而逢日墓、动墓、化墓，或世动而化出官鬼又入墓，皆谓随鬼入墓。官鬼为克身之神，墓为困陷之牢，世随鬼入墓，如人被恶吏拘入暗牢：占病主病入膏肓、缠绵难愈，占官讼防牢狱之灾，占出行防身陷险地、有去难回，占谋事主困顿难伸。解救之机在冲：墓库逢冲则开，故应期多在冲墓之日；子孙旺动制鬼，亦可化险。',related:['rumu','guizhi','yingqi']},
  {slug:'chishi',name:'持世',pinyin:'Chí Shì',english:'Six-Relative Sitting on the Self Line',category:'liuyao',shortDesc:'六亲临世爻为某亲持世，观何亲持世以定自身处境。',detail:'持世指卦中某一六亲恰临世爻（世爻即求测者自身），如官鬼临世爻为官鬼持世。古诀以持世之亲断自身处境：官鬼持世主忧患官非，占身防疾病官讼缠身；子孙持世主无忧无虑，官鬼受制、灾病自消，占病最喜；妻财持世主财禄有份，求财较利；父母持世主辛劳，为文书房屋之事奔波；兄弟持世主破耗，求财防人分夺、合作防争。然持世吉凶仍须以五行生克为本：官鬼持世而旺相有制，反主掌权得势；子孙持世而休囚，亦难制鬼，不可执歌断死。',related:['shiying','liuqin','yongshen-yao']},
  {slug:'huozhulin',name:'火珠林',pinyin:'Huǒ Zhū Lín',english:'Huo Zhu Lin (Coin Divination Classic)',category:'liuyao',shortDesc:'六爻占法经典，相传五代时出，以钱代蓍专重五行生克。',detail:'火珠林是六爻（纳甲筮法）最著名的占法典籍，一卷，旧题或云出于五代、托名麻衣道人所传，为六爻钱卜一系承前启后的纲领之书。其法不用《周易》卦爻辞占断，而以京房八宫、纳甲、世应、六亲为纲，专以五行生克论吉凶，问事必先用神，所谓「卦定根源，六亲为主；爻究旁通，五行而取」，确立了六爻断卦的基本法则。火珠林行世后，六爻遂脱离卦辞爻辞而自成体系，宋元以来的六爻诸书莫不祖述之，与《周易》古筮法并列为两大占筮传统。',related:['yaogua','jingshi-yixue','liuyao']},
  {slug:'zengshan-buyi',name:'增删卜易',pinyin:'Zēng Shān Bǔ Yì',english:'Zeng Shan Bu Yi (Liuyao Classic)',category:'liuyao',shortDesc:'清初野鹤老人所传六爻名著，重五行生克、卦例详实。',detail:'增删卜易是清代流传最广的六爻典籍，题野鹤老人著、门人李文辉增删，成书于康熙年间。全书以实战卦例为纲，纵论起卦装卦、用神取用、生克冲合、旬空月破、飞伏进退、应期诸法，主张断卦「以五行生克为主，不用星煞」，力辟以卦辞爻辞与神煞穿凿附会之弊，条理明晰、断语直截，收录数百真实卦例，供后学揣摩应验之道。其说承火珠林而益精，与《卜筮正宗》并为清代六爻两大宗匠之书，习六爻者几乎人手一编。',related:['huozhulin','bushi-zhengzong','liuyao']},
  {slug:'bushi-zhengzong',name:'卜筮正宗',pinyin:'Bǔ Shì Zhèng Zōng',english:'Bu Shi Zheng Zong (Liuyao Classic)',category:'liuyao',shortDesc:'清初王洪绪撰六爻规范之作，列十八论总断卦法。',detail:'卜筮正宗是清代六爻经典，作者王洪绪（王维德，号林屋山人），成书于康熙四十八年。全书十四卷，首列「辟谬」指摘诸家卦书之误，次以十八论详述装卦、世应、用神、原忌仇神、六神、月建日辰、动变、旬空月破、进神退神、飞伏、归魂游魂、反吟伏吟、应期等断卦法则，末附各门占验分类与卦例，体例谨严、论断精审，号为六爻正宗。王洪绪亦精外科医术，著《外科全生集》，卜筮正宗与增删卜易并称，同为清代及民国以来六爻学者入门与深造的标准读本。',related:['zengshan-buyi','huozhulin','yingqi']},
  {slug:'liuyao-quxiang',name:'六爻取象断事',pinyin:'Liù Yáo Qǔ Xiàng Duàn Shì',english:'Image-Based Reading in Liuyao',category:'liuyao',shortDesc:'五行生克定吉凶之外，以六神、卦宫、爻位、地支等取象断事之细节。',detail:'六爻断卦向分两层：一层以五行生克定吉凶大势，一层以取象断人事细节。取象所据有四：六神之象，青龙主喜庆酒色、朱雀主口舌文书、白虎主凶丧刑伤、玄武主暗昧盗贼、勾陈主田土迟滞、螣蛇主虚惊怪异；卦宫卦名之象，如得咸恒多主婚姻感应；爻位之象，初爻为足为地基、五爻为君为尊长，各应人事高低；地支万物类象，如子为水为鼠、午为火为马，兼配八卦五行推人事物情状。断卦以生克定其吉凶，以取象实其情状，如测失物，玄武临水爻则断物在近水暗处，两法相济，断语乃活。',related:['liushen','yaowei','shuogua']},
  // ===== 道学补充 · 教派宗派 (13) =====
  {slug:'tianshi-dao',name:'天师道',pinyin:'Tiān Shī Dào',english:'Celestial Masters Taoism',category:'daoxue',shortDesc:'东汉张道陵所创五斗米道，道教最早教团，后世正一之源。',detail:'天师道是道教最早的教团组织。东汉顺帝时沛人张道陵于鹤鸣山学道，奉老子为教祖，以符水咒法为人治病，从者出五斗米，故称五斗米道，又称米道、鬼道；因传道者称天师，后世谓之天师道。道陵立二十四治传教，其孙张鲁据汉中政教合一三十余年，后降曹操而道众北迁，道教遂广传中原。西晋后道陵后裔世居江西龙虎山，代代称天师，传承至今，与正一道合流而为符箓各派之宗主。天师道以符箓斋醮、劝善济人为特色，是早期道教与民间信仰结合最深的教团。',related:['zhengyi-dao','fulu','laojun']},
  {slug:'zhengyi-dao',name:'正一道',pinyin:'Zhèng Yī Dào',english:'Way of Orthodox Unity',category:'daoxue',shortDesc:'以符箓斋醮为主的教派，龙虎山张天师为宗主，元后统诸符箓派。',detail:'正一道又称正一派、正一盟威道，是道教两大教派之一，与全真道相对。相传张道陵得太上老君授「正一盟威之道」，故其后裔所传即正一之教；唐宋以来符箓各派（上清、灵宝、天师诸派）多有「正一」之号，元代敕令正一天师统领江南诸路符箓派，遂合而为一。正一道士不必出家，可娶妻生子、食荤饮酒，称火居道士或俗家道士；其法以符箓、咒术、斋醮、驱邪度亡为主，龙虎山天师府为祖庭，与茅山、阁皂山并称符箓三山。今正一道仍为海峡两岸及海外道教之主流。',related:['tianshi-dao','fulu','shoulu']},
  {slug:'quanzhen-dao',name:'全真道',pinyin:'Quán Zhēn Dào',english:'Complete Perfection Taoism',category:'daoxue',shortDesc:'金代王重阳创立，主清修内丹、出家住观，与正一并为两大派。',detail:'全真道是金代王重阳（王喆）在山东创立的道教新教派，是道教北宗清修一系的主体。王重阳主张儒释道三教合一，以《道德经》《般若心经》《孝经》教人，重内丹清修而不尚符箓，倡性命双修、先性后命，戒荤酒、讲苦己利人；其弟子马钰、丘处机等七人即全真七子（七真），丘处机西觐成吉思汗一言止杀，全真因之大盛，历代掌教居燕京长春宫（今白云观）。全真道士出家住宫观、茹素守戒，立丛林制度，元以后与正一道分统南北道教，为今日道教两大派之一。',related:['beizong','wuzu-qizhen','longmen-pai']},
  {slug:'nanzong',name:'南宗',pinyin:'Nán Zōng',english:'Southern School (Neidan)',category:'daoxue',shortDesc:'以张伯端为祖的内丹一派，主先命后性，与北宗相对。',detail:'南宗是内丹修炼的一大宗派，以北宋张伯端（号紫阳，著《悟真篇》）为祖师，因其传法于南方、与金代全真之北宗相对而得名。南宗传法谱系为张伯端传石泰、石泰传薛式、薛式传陈楠、陈楠传白玉蟾，称南五祖。丹法上南宗主「先命后性」：先以命功炼精化气、筑基固本，再修性功了心见性，与北宗先性后命的进路相反，然终归性命双修。白玉蟾以后南宗多归并入全真，然其丹法与著作（悟真篇一系）流传极广，影响深远。',related:['beizong','wuzhenpian','dandao-wuzu']},
  {slug:'beizong',name:'北宗',pinyin:'Běi Zōng',english:'Northern School (Neidan)',category:'daoxue',shortDesc:'以王重阳全真一系为主的内丹宗派，主先性后命、清修为宗。',detail:'北宗是内丹修炼的一大宗派，指以金代王重阳及全真七子为代表的一系，因传法于北方而得名，与张伯端之南宗相对。北宗丹法主「先性后命」：以识心见性、清净无为为先，性功了彻而后修命，所谓「三分命功，七分性功」，不尚符箓咒术，以清修苦行为宗，主张出家住观、断绝尘缘，将内丹修炼与道教戒行伦理结合。北宗经丘处机等七真弘扬而大盛，元代以后道教内丹诸派多归其统绪，与南宗并称丹道两大宗派，然南北之辨要在入手功夫之先后，非道旨有异。',related:['nanzong','quanzhen-dao','xingming-shuangxiu']},
  {slug:'wuzu-qizhen',name:'五祖七真',pinyin:'Wǔ Zǔ Qī Zhēn',english:'Five Patriarchs and Seven Perfected',category:'daoxue',shortDesc:'全真道尊奉的祖师谱系：北五祖南五祖与王重阳七弟子。',detail:'五祖七真是全真道与内丹家的祖师谱系。五祖分南北：北五祖指全真道尊奉的少阳派传承——东华帝君王玄甫、正阳帝君钟离权、纯阳帝君吕洞宾、刘海蟾、王重阳；南五祖则指张伯端、石泰、薛式、陈楠、白玉蟾一系。七真指王重阳的七大弟子：马钰（丹阳）、谭处端（长真）、刘处玄（长生）、丘处机（长春）、王处一（玉阳）、郝大通（广宁）、孙不二（清静），七真各开一派，其中丘处机一系衍为龙门派，最称兴盛。五祖七真之说反映了全真道以钟吕金丹道为渊源、以内丹性命之学为正传的谱系观念。',related:['quanzhen-dao','longmen-pai','neidan']},
  {slug:'longmen-pai',name:'龙门派',pinyin:'Lóng Mén Pài',english:'Longmen (Dragon Gate) School',category:'daoxue',shortDesc:'全真道最大支派，丘处机所开，清代王常月中兴。',detail:'龙门派是全真道影响最大的支派，尊全真七子之首丘处机（号长春子）为祖师。丘处机曾西行雪山觐见成吉思汗，一言止杀，被尊为神仙，住燕京长春宫（今北京白云观），全真由此鼎盛；其门徒尹志平、李志常相继掌教，丘氏一系遂称龙门派。明末清初，龙门第七代律师王常月于白云观中兴龙门，开坛传戒，整顿清规，使龙门派遍传南北，成为全真道主流，世称「龙门中兴」。龙门派以清修内丹与戒律传戒并重，至今全真道士多属龙门法脉。',related:['quanzhen-dao','wuzu-qizhen','zuowang']},
  {slug:'sanfeng-pai',name:'三丰派',pinyin:'Sān Fēng Pài',english:'Sanfeng School',category:'daoxue',shortDesc:'尊张三丰为祖的武当道派，内丹与武术合一，亦称隐仙派。',detail:'三丰派又称武当派、隐仙派，是明清以来以武当山为中心、尊元末明初高道张三丰为祖师的道派。张三丰名君实，号三丰，辽东懿州人，行踪诡秘，明太祖、成祖屡遣使求访不得，传说其曾隐武当修炼，创内家拳术与睡功（蛰龙法），以内丹炼养与导引技击相结合为特色，主张「内炼精气神，外练筋骨皮」。三丰派在明代极受推崇，成祖大修武当宫观，明清武侠传说又附会出太极拳等故事，使三丰派声名远播，武当山至今为道教名山与武术圣地。',related:['neidan','daoyin','quanzhen-dao']},
  {slug:'shangqing-pai',name:'上清派',pinyin:'Shàng Qīng Pài',english:'Supreme Clarity School',category:'daoxue',shortDesc:'以茅山为本山、奉上清经的道派，重存思内视，陶弘景集大成。',detail:'上清派是道教重要符箓宗派，以茅山为本山，故又称茅山宗。东晋兴宁年间杨羲、许谧等称魏夫人等仙真降授《上清经》，后经王灵期传布，南朝齐梁时陶弘景隐居茅山，搜集整理上清经法，著《真诰》《登真隐诀》，上清派遂成规模。上清派重存想思神、内视咽液、诵经修行，虽亦用符箓而较天师道更重个人修炼，经典以《大洞真经》《黄庭经》为主。历代高道如司马承祯、李含光等皆出此派，与龙虎山正一、阁皂山灵宝并称符箓三山。',related:['lingbao-pai','cunxiang','huangtingjing']},
  {slug:'lingbao-pai',name:'灵宝派',pinyin:'Líng Bǎo Pài',english:'Numinous Treasure School',category:'daoxue',shortDesc:'以阁皂山为本山、奉灵宝经的道派，重斋醮济度，葛氏家族所传。',detail:'灵宝派是道教符箓宗派之一，以阁皂山（今江西樟树）为本山，奉《灵宝经》为宗。灵宝经系传说由葛玄（葛仙翁）传下，经葛洪等葛氏家族保存传布，东晋末至南朝陆续出经，其中《灵宝无量度人上品妙经》为万法之宗；南朝陆修静整理灵宝经目，融汇三洞科仪，使灵宝斋法大备。灵宝派以斋醮度人为主旨，重济度幽冥、祈福禳灾，其斋法科仪对后世道教仪式影响极深，所谓「灵宝之斋，科仪最盛」。唐宋时阁皂山灵宝与茅山上清、龙虎山正一合称符箓三山，元代以后多归并于正一。',related:['shangqing-pai','zhaijiao','fulu']},
  {slug:'jingming-dao',name:'净明道',pinyin:'Jìng Míng Dào',english:'Pure Brightness School',category:'daoxue',shortDesc:'尊许逊为祖的道派，倡忠孝净明，融合儒道，盛于宋元西山。',detail:'净明道是宋元间兴起于江西西山（今南昌）的道教宗派，尊东晋道士许逊（许真君，曾为旌阳县令，世称许旌阳）为祖师。相传许逊得道拔宅飞升，西山万寿宫为其遗迹；南宋以后有何真公等托许逊降授净明忠孝之法，元代刘玉重振其教，以「净明」名派。净明道以忠孝为修道之本，主张「以忠孝廉慎为基，以调摄心性为务」，谓心性明净则道自通，明显融合儒家伦理与道教修炼，所谓「净明只是正心诚意」，为三教合一思潮下的典型道派。',related:['tianshi-dao','gongguoge','quanzhen-dao']},
  {slug:'shenxiao-pai',name:'神霄派',pinyin:'Shén Xiāo Pài',english:'Divine Empyrean School',category:'daoxue',shortDesc:'北宋兴起的雷法道派，王文卿开宗，行五雷法，盛于宋徽宗朝。',detail:'神霄派是北宋末兴起的道教雷法宗派，因奉神霄玉清天王（即南极长生大帝）等九宸上帝而得名。北宋末道士王文卿（江西南丰人）得雷法之传，开神霄一宗，其后萨守坚、林灵素等继之；林灵素得幸于宋徽宗，大倡神霄之说，徽宗自号道君皇帝，神霄派一时贵盛，称「神霄雷法」。神霄派以五雷正法祈雨禳灾、驱邪治病，主张内炼为本、外用为末——先于身中运炼精气神，然后召雷行法，内丹与符法合一。南宋以后神霄与清微诸派并行，元代多归正一。',related:['leifa','fulu','neidan']},
  {slug:'leifa',name:'雷法',pinyin:'Léi Fǎ',english:'Thunder Rites',category:'daoxue',shortDesc:'道教法术大宗：内炼五脏之气，外用符咒召雷致雨、驱邪镇煞。',detail:'雷法是宋元道教法术中最有体系的一门，以召役雷神、行雷致雨、驱邪镇煞、治病消灾为用，神霄、清微、天心诸派皆以行雷法著称。雷法理论强调「内炼外行」：法师平日以内丹功夫炼养五脏之气，使身中五雷（五脏真气）充盈，行法时掐诀步罡、书符念咒，以内气合外神，召遣雷部将吏行事，所谓「道法以气为主」「内道外法」。雷法中五雷（天雷、地雷、水雷、神雷、社雷等说）分司不同职掌。雷法把内丹修炼与符箓法术打通，是道教法术史上最精密的创造之一。',related:['shenxiao-pai','bugang-tadou','fulu']},
  // ===== 道学补充 · 教义戒劝 (7) =====
  {slug:'chengfu',name:'承负',pinyin:'Chéng Fù',english:'Inherited Burden (Cheng Fu)',category:'daoxue',shortDesc:'道教特有的报应观：先人过失殃及后人，行善积德可解。',detail:'承负是道教特有的报应理论，见于早期经典《太平经》，与佛教因果报应说不同而别具一格。「承者，乃谓先人本承天心而行，小小失之不自知，用日积久，相聚为多，今后生人反无辜蒙其过谪，连传被其灾，故前人为承，后人为负也」，意谓先人作恶，其过失积累而由后人承受灾祸；反之先人积善，后人亦蒙余庆。承负可及数世，故《太平经》劝人积德行善以断承负之厄。承负说把家族伦理与善恶报应结合，深刻塑造了道教与民间「前人栽树后人乘凉」「祖上积德」的观念。',related:['gongguoge','taishang-ganyingpian','tianshi-dao']},
  {slug:'gongguoge',name:'功过格',pinyin:'Gōng Guò Gé',english:'Merit-Demerit Ledger',category:'daoxue',shortDesc:'道教劝善法门：逐日记录善恶功过，折算以自省迁善。',detail:'功过格是道教劝善修行的实用方法，将人的言行按善恶分为功、过两类，各定分值，逐日记录、按月小结，以积累功德、警惕过失。现存最早者为南宋《太微仙君功过格》，道教谓其由太微仙君降授，功格三十六条、过律三十九条，如救济一人为十功、杀一生命为十过之类；明清之际功过格大行于世，袁了凡《了凡四训》所述云谷禅师授功过格、力行改命之事流传极广，成为儒家士大夫修身与道教积善融合的典范。功过格以量化的自律促进道德实践，影响远及今日之善行记录传统。',related:['chengfu','taishang-ganyingpian','jingming-dao']},
  {slug:'taishang-ganyingpian',name:'太上感应篇',pinyin:'Tài Shàng Gǎn Yìng Piān',english:'Treatise of the Exalted One on Response',category:'daoxue',shortDesc:'道教第一劝善书：祸福无门惟人自召，善恶之报如影随形。',detail:'太上感应篇是道教最著名的劝善书，托名太上老君所说，成书约在北宋以前，南宋李昌龄为之作传注而大行。全篇以「祸福无门，惟人自召；善恶之报，如影随形」开宗，历举善恶条目百余条，劝人「是道则进，非道则退」，恤孤怜贫、济人之急、不履邪径，谓天地有司过之神依人所犯轻重以夺人算，积善则天必降福，积恶则天必降祸。感应篇把道教承负报应与儒家伦理融为一体，文字浅近、便于传诵，宋元以来印行无量，与《文昌帝君阴骘文》《关圣帝君觉世真经》并称三大劝善书。',related:['chengfu','gongguoge','laojun']},
  {slug:'wuwei',name:'无为',pinyin:'Wú Wéi',english:'Non-Action (Wu Wei)',category:'daoxue',shortDesc:'道家的根本主张：不妄为、顺自然，无为而无不为。',detail:'无为是道家与道教的核心观念，出自《道德经》：「道常无为而无不为」「为无为，则无不治」。无为并非无所作为，而是不妄为、不强为，顺应事物本然之理而因势利导，如天道不言而四时行、百物生。老子以无为治国：我无为而民自化，我好静而民自正；道教则以无为为修身之要：清静寡欲、不争不扰，使身心合于自然。后世又把无为与有为相对而言，反对苛政与矫饰，主张「无为而治」，成为中国传统政治哲学与处世智慧的重要一翼。',related:['daofa-ziran','qingjing','dao']},
  {slug:'daofa-ziran',name:'道法自然',pinyin:'Dào Fǎ Zì Rán',english:'Dao Follows Nature',category:'daoxue',shortDesc:'道德经名句：人法地地法天天法道，道之本性即自然而然。',detail:'道法自然出自《道德经》第二十五章：「人法地，地法天，天法道，道法自然。」谓道的运行以自然而然为法则，道本身无为无造、自己如此，万物亦各顺其本性而生化。此处的自然不是指自然界，而是「自己而然、本来如此」之意。道教以道法自然为根本教义与修行纲领：养生则顺四时阴阳、不逆生理，处世则顺物之性、不强加于人，治国则清静无为、与民休息。道法自然把宇宙观、人生观与养生观统一起来，是道家思想最凝练的表达，至今仍是中国人精神生活的经典命题。',related:['wuwei','dao','qingjing']},
  {slug:'qingjing',name:'清静',pinyin:'Qīng Jìng',english:'Clarity and Stillness',category:'daoxue',shortDesc:'道之本性：清静为天下正，道教修持以清静为本。',detail:'清静是道家道教的核心修持观念，谓道体清静无为，人心亦当清静寡欲以合于道。《道德经》言「清静为天下正」「我好静而民自正」；道教《太上老君说常清静经》发挥其义，开篇即云「大道无形，生育天地；大道无情，运行日月；大道无名，长养万物」，劝人「遣其欲而心自静，澄其心而神自清」，人能常清静则天地悉皆归。清静与寡欲相连，为内丹静功与斋戒之本，宋明理学「主静」「涵养」之说亦深受其影响，清静无为遂成道教与道家修养的代名词。',related:['daofa-ziran','wuwei','zuowang']},
  {slug:'daojiao-jielv',name:'道教戒律',pinyin:'Dào Jiào Jiè Lǜ',english:'Taoist Precepts and Rules',category:'daoxue',shortDesc:'道教约束身心的规戒：老君五戒、初真中极天仙三坛大戒等。',detail:'道教戒律是约束道士身心言行、防非止恶的规条。戒以禁恶，律以惩违。早期有《老君想尔戒》《道德尊经想尔戒》，后增为九戒、二十七戒等；全真道立教尤重戒律，传戒分三坛：初真戒（十戒）、中极戒（三百戒）、天仙大戒（无量大戒），须依次受持，称三坛大戒；正一派则受箓而不重传戒。常见戒条如不杀、不盗、不淫、不妄语、不饮酒为老君五戒之要。戒律与清规（宫观内部管理制度）相辅而行，全真道士出家受戒方为正式道人，戒律是道教伦理的制度化体现。',related:['quanzhen-dao','shoulu','zhengyi-dao']},
  // ===== 道学补充 · 修炼方术 (17) =====
  {slug:'cunxiang',name:'存想',pinyin:'Cún Xiǎng',english:'Visualization (Cun Xiang)',category:'daoxue',shortDesc:'道教修炼法：凝神观想身中神真、日月星斗与丹田真气。',detail:'存想又称存思、存神，是道教最重要的修炼方法之一，指收视返听、凝神静虑，在心中观想一定的对象以收摄精神、感召神气。观想的对象多种多样：或存思身中诸神（如五脏之神、三部八景神），或存想日月星斗、五方真气飞入身中，或内观丹田之中真气运行。上清派最重存想，黄庭经即存思五脏神的经典；存想可使精神专一、以意引气，与内观、守一相通，为内丹兴起前道教修炼的主流方法，至今仍为气功养生的基本功法之一。',related:['neiguan','shouyi','shangqing-pai']},
  {slug:'neiguan',name:'内观',pinyin:'Nèi Guān',english:'Inner Observation (Nei Guan)',category:'daoxue',shortDesc:'反观内视己身之神气，澄心静念，如内观经所谓内观己身。',detail:'内观又称内视、返观，是道教静功修炼法门，指收视返听、向内心观照，使精神不外驰而反观自身。《太上老君内观经》说：「内观之道，静神定心，乱想不起，邪妄不侵。」内观既观照心念之起灭（观心），亦内视身中之脏腑真气运行（内视），与存想相较更重在向内省察而非向外存思。修内观者先须闭目静坐、调匀气息，于静定中观照内景，日久则妄念自息、神气自凝，与坐忘、心斋同为「收视返听」一路的性功功夫，为内丹筑基所本。',related:['cunxiang','zuowang','xinzhai']},
  {slug:'shouyi',name:'守一',pinyin:'Shǒu Yī',english:'Guarding the One',category:'daoxue',shortDesc:'早期道教根本修法：抱一守真、守神不离，使精炁神凝而不散。',detail:'守一是道教早期修炼的根本方法，渊源于《道德经》「载营魄抱一，能无离乎」「圣人抱一为天下式」。道教以为天地人皆有「一」——人身之中亦有真一之神，守一即使精神专一守持身中神气，不使外驰散失。太平经极重守一，谓「守一明法，长寿之根」；上清派又有守真一、守三一等细分，配存想丹田与身神而行。守一与存想、内观相通而更重抱元守朴、以静制动，为内丹兴起前道教炼养的核心法门，后世内丹「凝神入气穴」之说实承其绪。',related:['cunxiang','neiguan','jingqishen']},
  {slug:'tiaoxi',name:'调息',pinyin:'Tiáo Xī',english:'Regulating the Breath',category:'daoxue',shortDesc:'调匀呼吸之静功基础：绵绵若存、心息相依，为入静之门。',detail:'调息是道教静功与内丹修炼的基础功夫，指通过意念调节呼吸，使之深、细、匀、长，绵绵若存。调息法门有数息（默数呼吸以收心）、随息（心随气息出入）、听息（以耳听气）等，其要在息调则心定、心定则息调，心息相依而不执着于息。道教认为「一呼一吸谓之息」，息为气之表、神之驭，调息能平心火、补肾水、安神聚气，故内丹下手先调息，胎息亦由深长调息渐进而得。调息须顺其自然，忌强忍闭气，气功养生皆以此为入门第一课。',related:['taixi','zhuji','zuowang']},
  {slug:'tuna',name:'吐纳',pinyin:'Tǔ Nà',english:'Exhalation-Inhalation (Tu Na)',category:'daoxue',shortDesc:'吐故纳新之行气法：呼出浊气、吸入清气，配导引而行。',detail:'吐纳指吐出体内浊气、吸纳天地清气的行气养生方法，语出《庄子·刻意》「吹呴呼吸，吐故纳新，熊经鸟申，为寿而已矣」。道教行气之法多从吐纳入手：或吐纳以调脏腑之气（如六字诀分嘘呵呼呬吹嘻以泻五脏之浊），或于清晨面向东方吸纳生气，配合咽津、叩齿、导引等术行之。吐纳能清肺胃之浊、养五脏之真，与胎息相较为浅层呼吸功夫，然简便易行，为古代导引养生之普遍法门，今之气功深呼吸锻炼即其遗绪。',related:['daoyin','liuzijue','waqi']},
  {slug:'daoyin',name:'导引',pinyin:'Dǎo Yǐn',english:'Daoyin (Guiding-Qi Exercise)',category:'daoxue',shortDesc:'以肢体屈伸俯仰配合呼吸的养生术，熊经鸟申，动以养形。',detail:'导引是古代养生术的重要门类，指通过肢体的屈伸俯仰、旋转开合等运动，配合呼吸吐纳以导气令和、引体令柔，从而流通气血、祛病延年。《庄子》已有「熊经鸟申」之说，《抱朴子》谓「夫导引疗未患之疾，通不和之气，动之则百关气畅」。导引可单行，亦常与按摩（按跷）并称「导引按跷」；五禽戏、八段锦、易筋经皆由导引发展而来，为后世体操与气功的先声。道教养生以导引动形、吐纳调气、静坐养神三者配合，动静相济。',related:['wuqinxi','baduanjin','tuna']},
  {slug:'wuqinxi',name:'五禽戏',pinyin:'Wǔ Qín Xì',english:'Five Animals Exercise',category:'daoxue',shortDesc:'华佗所创养生操：模仿虎鹿熊猿鸟五禽之戏以活动筋骨。',detail:'五禽戏相传为东汉名医华佗所创的导引养生术，模仿五种动物的形态动作以锻炼身体，载于《后汉书·华佗传》：华佗谓「人体欲得劳动，但不当使极耳。动摇则谷气得消，血脉流通，病不得生，譬犹户枢不朽是也」，因仿虎、鹿、熊、猿、鸟（一作鹤）之戏，以除疾利足。虎戏主练筋骨刚猛，鹿戏主练腰腿灵便，熊戏主练脾胃厚重，猿戏主练身手敏捷，鸟戏主练胸臂轻扬。五禽戏流传近两千年，历代增删演化，至今仍为流行的健身功法，被誉为中国最早的系统保健体操。',related:['daoyin','baduanjin','huatuo']},
  {slug:'baduanjin',name:'八段锦',pinyin:'Bā Duàn Jǐn',english:'Eight Pieces of Brocade',category:'daoxue',shortDesc:'八节成套的导引功法，南宋已有记载，坐立二式流传最广。',detail:'八段锦是流传最广的传统导引功法之一，共八节动作，如锦缎之华美成套，故名八段锦。南宋曾慥《道枢》已载八段锦口诀，有坐式（钟离八段锦）与立式之分，今通行立式八段锦口诀为：两手托天理三焦，左右开弓似射雕，调理脾胃须单举，五劳七伤往后瞧，摇头摆尾去心火，两手攀足固肾腰，攒拳怒目增气力，背后七颠百病消。八段锦动作舒缓、刚柔相济，配呼吸吐纳以调脏腑、通经络，宋元以来为道士与民众养生所习，至今仍是中国最普及的传统健身术。',related:['daoyin','wuqinxi','liuzijue']},
  {slug:'liuzijue',name:'六字诀',pinyin:'Liù Zì Jué',english:'Six-Character Breathing Method',category:'daoxue',shortDesc:'以嘘呵呼呬吹嘻六字吐气，配五脏祛病延年的功法。',detail:'六字诀是道教与中医共用的呼吸养生功法，以嘘、呵、呼、呬、吹、嘻六个字的吐气发声分别调理肝、心、脾、肺、肾、三焦之气：嘘字诀泄肝之郁气，呵字诀清心之邪火，呼字诀健脾胃之运，呬字诀理肺之壅，吹字诀固肾之虚，嘻字诀通三焦之气。行功时口吐字音而不出声，呼气念字、吸气自然，谓「嘘则通肝，呵则通心，呼则通脾，呬则通肺，吹则通肾，嘻则通三焦」。六字诀源出陶弘景《养性延命录》所载六气法，为吐纳导引中的重要功法。',related:['tuna','daoyin','wuzang-liufu']},
  {slug:'zuowang',name:'坐忘',pinyin:'Zuò Wàng',english:'Sitting in Forgetfulness',category:'daoxue',shortDesc:'庄子之法：离形去知、同于大通；司马承祯坐忘论为修心要典。',detail:'坐忘是道家修心的最高境界之一，语出《庄子·大宗师》：颜回曰「堕肢体，黜聪明，离形去知，同于大通，此谓坐忘」，谓忘掉形体智识、超越物我对立而与大道合一。唐代道士司马承祯著《坐忘论》一卷，分敬信、断缘、收心、简事、真观、泰定、得道七篇，把庄子的坐忘发展为系统的修心次第，主张「学道之初，要须安坐，收心离境，住无所有」，以静定中渐入忘境、了悟真性。坐忘与心斋并称道教性功两大法门，对后世内丹、宋明理学主静之说均有深远影响。',related:['xinzhai','neiguan','xingming-shuangxiu']},
  {slug:'xinzhai',name:'心斋',pinyin:'Xīn Zhāi',english:'Fasting of the Mind',category:'daoxue',shortDesc:'庄子之法：虚而待物，唯道集虚，收视返听以养心体道。',detail:'心斋是庄子提出的体道修养方法，见于《庄子·人间世》：颜回问仲尼何谓心斋，答曰「若一志，无听之以耳而听之以心，无听之以心而听之以气。听止于耳，心止于符。气也者，虚而待物者也。唯道集虚。虚者，心斋也」。其旨在于专一心志，由耳听而心听、由心听而气听，层层放下感官思虑，使心虚静空灵以容纳大道，与「坐忘」同为离形去智、虚己体道之方。后世道教以心斋为斋法中最高者（所谓「斋者齐洁净也」，心斋即心之斋戒），道教斋醮科仪亦取斋心之义。',related:['zuowang','neiguan','dao']},
  {slug:'huandu',name:'环堵',pinyin:'Huán Dǔ',english:'Ring Chamber (Seclusion Room)',category:'daoxue',shortDesc:'全真道闭关修炼之静室：环墙一室，坐圜其中，杜门用功。',detail:'环堵又称环堵室、静圜，是全真道与内丹修炼者闭关静修之所。语出《庄子·庚桑楚》「吾闻至人，尸居环堵之室」，谓四面环墙、仅容一人的小室。全真道士修炼到一定阶段，须入环堵中百日或更久的「坐圜」闭关，其间杜门谢客、断绝外缘，日中一食，专事静坐内炼，期满方出。环堵之制体现了全真道苦修清修之风，元代全真道士多有坐环数十次者，被视为磨炼心性、精进丹功的重要关期。今之道观亦有「闭关房」「圜堂」为其遗制。',related:['quanzhen-dao','beizong','zuowang']},
  {slug:'lianji',name:'炼己',pinyin:'Liàn Jǐ',english:'Refining the Self',category:'daoxue',shortDesc:'内丹入手功夫：克己除妄、凝神静定，为筑基前之准备。',detail:'炼己是内丹修炼的入手功夫，指先于身心上做克己持心的准备：除却嗜欲妄念，使心清意定、神气安和，然后方可谈筑基炼丹。「己」即己土、本性真意，炼己即以真意制伏妄念，如《悟真篇》所谓「若要修成九转，先须炼己持心」。丹家以为炼己不纯则筑基难固，心猿意马则药物走失，故有「炼己之功，最为要务」之说。炼己与佛家持戒、儒家克己相通，重在性功，贯穿丹道始终，非仅初阶一段功夫；各家丹书每以炼己为第一关键。',related:['zhuji','huohou','neiguan']},
  {slug:'wogu',name:'握固',pinyin:'Wò Gù',english:'Fist Clenching (Wo Gu)',category:'daoxue',shortDesc:'道教养生手式：四指握拇指如婴儿握固，以固精安神。',detail:'握固是道教养生与修炼常用的一种手式：以其余四指握住大拇指，握拳如婴儿之状。《道德经》说「骨弱筋柔而握固」，谓赤子精气纯全、天然能握固，道教因以握固为固摄精气之法。修炼静坐、行气导引时，两手握固置于膝上，可安定神气、防止精气外泄，亦用于叩齿咽津等功法之配合；道家认为握固能「固精明目，留年还魄」，驱避邪气，故道士行法、存想时亦常握固。握固法简效宏，为养生家所普遍采用。',related:['tiaoxi','daoyin','jingqishen']},
  {slug:'fufu',name:'服饵',pinyin:'Fú ěr',english:'Ingesting Herbal Elixirs',category:'daoxue',shortDesc:'服食药物以养生延年之法：草木之饵如黄精茯苓芝术等。',detail:'服饵又称服食，指服食药物以求养生延年的道教方术，与辟谷、导引并称早期道教三大养生手段。饵有草木之饵与金石之饵：草木类如黄精、茯苓、枸杞、灵芝、白术、地黄等，道家以为久服可轻身益气、延年不老，《神农本草经》所载上品药多此类；金石类则属外丹服食，因含毒致死者多，后世渐废。服饵讲究择时采制、配合吐纳辟谷而行，道教医药之学因之大兴，孙思邈《千金方》即多录服饵方。今之药膳养生传统即承服饵之余绪。',related:['bigu','waidan','daoyin']},
  {slug:'sanhua-juding',name:'三花聚顶',pinyin:'Sān Huā Jù Dǐng',english:'Three Flowers Gather at the Crown',category:'daoxue',shortDesc:'内丹功夫纯熟之象：精炁神三华聚于泥丸，五气朝元。',detail:'三花聚顶是内丹修炼的术语，花通华，三花指精、气、神三宝之华，聚顶谓三华会聚于头顶泥丸宫（上丹田）。丹家以为修炼到炼精化气、炼气化神功夫纯熟，精炁神三者凝炼而上升会聚于顶，即三花聚顶；同时五脏真气（五气）各朝其元，归于中黄，称五气朝元，故有「三花聚顶，五气朝元」之说，形容大周天功成、神气归一的上乘境界。此语本为内丹术语，后世小说戏曲借以形容得道仙人法力圆满，遂成家喻户晓之语，然其本义在身内精气神之炼化。',related:['lianjing-huaqi','lianqi-huanshen','sandantian']},
  {slug:'huozishi',name:'活子时',pinyin:'Huó Zǐ Shí',english:'Living Zi Hour (Qi Rising Moment)',category:'daoxue',shortDesc:'内丹火候术语：一阳初动之机，不拘夜半，随时可生。',detail:'活子时是内丹修炼火候的重要概念，与固定于夜半的「死子时」相对。丹家以一日之子时为阴极阳生之候，然人身真气之发动不必候于夜半：行功静定之中，恍惚杳冥之际忽觉一阳来复、丹田融暖、外肾兴起（或阳举、或气动之景），此先天真阳初动之机即是活子时。丹道采药起火必于活子时行之，所谓「活子时者，乃身中一阳初动之候」，须及时以武火采炼、勿令走失。活子时的把握全在功夫与觉照，为丹道「火候」最难言传处之一。',related:['huohou','zhuji','qiangang']},
  {slug:'sanhua',name:'还丹',pinyin:'Huán Dān',english:'Returned Elixir (Huan Dan)',category:'daoxue',shortDesc:'丹道要旨：抽坎填离、还精补脑，使神气复返先天纯阳。',detail:'还丹是内丹修炼的核心术语，谓炼功使精气神凝炼成丹，复还人体先天本元之态。「还」之义，取返本还元：人自先天纯阳（乾）因情欲亏损而落为后天坎离，修炼则取坎中真阳填离中真阴，使离复还乾体，故丹经有「取坎填离」「还精补脑」之说。还丹有大小之分：炼精化气、打通任督所得称小还丹（玉液还丹）；大周天功深、神气大凝称大还丹（金液还丹）。还丹既成，则生机内固、寿元可延，为内丹由筑基进于温养的关键一步，与三花聚顶、五气朝元之象相联。',related:['qiangang','lianjing-huaqi','liqi']},
  {slug:'xian-wudeng',name:'仙有五等',pinyin:'Xiān Yǒu Wǔ Děng',english:'Five Grades of Immortals',category:'daoxue',shortDesc:'钟吕丹道对仙的品分：鬼仙人仙地仙神仙天仙。',detail:'仙有五等是《钟吕传道集》对内丹成就等级的品分，吕洞宾答钟离权问而列五等：鬼仙，修性不修命、阴灵不散，只出阴神，五仙之最下；人仙，修命功得安乐延年之法，形质坚固而不脱凡；地仙，炼形住世、长生不死，陆地神仙；神仙，脱质升仙、超凡入圣，阳神出入自如；天仙，传道度人、功行圆满，升入洞天为天仙。五等之辨贯穿性命双修之旨：偏于性者止于鬼仙，偏于命者止于地仙，必性命双修、功行两全方臻神仙天仙。此说为道教内丹品仙的经典框架。',related:['zhensren','xingming-shuangxiu','shenxian']},
  // ===== 道学补充 · 经籍神祇 (10) =====
  {slug:'cantongqi',name:'周易参同契',pinyin:'Zhōu Yì Cān Tóng Qì',english:'Kinship of the Three (Cantong Qi)',category:'daoxue',shortDesc:'东汉魏伯阳撰，以易卦言丹道，号万古丹经王。',detail:'周易参同契是道教丹经之祖，东汉魏伯阳撰，三卷。「参同」谓大易、黄老、炉火三家之理参合而同契，书中以《周易》卦爻、阴阳消息比附炼丹：既言外丹炉火铅汞，又隐寓内丹精气神之炼养，纳甲、十二消息卦、卦爻火候之说皆具于其中，文辞古奥隐晦，号称难读。后世注家蜂起，五代彭晓、宋代朱熹（化名崆峒道士邹訢）皆有注，内丹家奉之为万古丹经王，谓钟吕金丹道与全真、南宗诸派皆渊源于此，在中国化学史与修炼史上均有崇高地位。',related:['neidan','yueti-najia','jindan']},
  {slug:'wuzhenpian',name:'悟真篇',pinyin:'Wù Zhēn Piān',english:'Awakening to Reality (Wu Zhen Pian)',category:'daoxue',shortDesc:'北宋张伯端撰，南宗丹法纲领，以诗词阐内丹之道。',detail:'悟真篇是北宋张伯端（紫阳真人）所著内丹经典，以诗词形式阐发丹道，与《周易参同契》并称丹经双璧。全书七言律诗十六首以象二八之数，绝句六十四首以应六十四卦，外加西江月词十二首等，总言性命双修、先命后性之旨，主张「学仙须是学天仙，惟有金丹最的端」，力辟旁门小术，谓内丹以人体精气神为药物、以自身为炉鼎，反对盲目烧炼外丹。张伯端一系遂为南宗，悟真篇为南宗祖经，注解极多，明清以来流传极广，是研究道教内丹思想最重要的文献之一。',related:['nanzong','neidan','cantongqi']},
  {slug:'huangtingjing',name:'黄庭经',pinyin:'Huáng Tíng Jīng',english:'Yellow Court Classic',category:'daoxue',shortDesc:'道教上清经典，分内外景经，主存思五脏之神与丹田黄庭。',detail:'黄庭经是道教重要经典，分《黄庭内景经》《黄庭外景经》两种，为早期上清派所重。黄庭指身中脾土中央与丹田要窍，经中历述人体各部皆有神主之：发神、脑神、眼神、五脏六腑之神及三部八景诸神，各有姓字服色，教人存思身神、漱咽津液、固精炼气，以养生长生，所谓「黄庭内景，存思之神」。外景经文字较古，相传王羲之书《黄庭经》换鹅即此（一说为外景经）。黄庭经上承存思之法、下启内丹之学，是道教从存想过渡到内丹的桥梁性经典，历代诵习注疏不绝。',related:['shangqing-pai','cunxiang','sandantian']},
  {slug:'daozang',name:'道藏',pinyin:'Dào Zàng',english:'Taoist Canon',category:'daoxue',shortDesc:'道教经书总集，明正统道藏五千三百余卷，三洞四辅分类。',detail:'道藏是道教经籍的总集，仿佛藏之例编纂。道教经书汇辑始于南北朝，唐代编《开元道藏》，宋金元历代续修，现存最完整者为明《正统道藏》（五千三百余卷）与《万历续道藏》，共收书约一千五百种，为研究道教与中国古代文化的渊薮。道藏分类用三洞四辅十二类之制：三洞为洞真（上清经）、洞玄（灵宝经）、洞神（三皇经），四辅为太玄、太平、太清、正一诸部辅翼三洞，十二类则按文体分本文、神符、玉诀、灵图、谱录、戒律、威仪、方法、众术、记传、赞颂、章表。今有敦煌道经与《中华道藏》可供参稽。',related:['shangqing-pai','lingbao-pai','fulu']},
  {slug:'dongtian-fudi',name:'洞天福地',pinyin:'Dòng Tiān Fú Dì',english:'Grotto-Heavens and Blissful Lands',category:'daoxue',shortDesc:'道教神仙所居之名山胜地：十大洞天、三十六小洞天、七十二福地。',detail:'洞天福地是道教对神仙所居名山胜境的总称，谓山中别有洞天，为仙人治所与修道佳地。唐代司马承祯《天地宫府图》等列：十大洞天（如王屋山小有清虚洞天、委羽山大有空明洞天等）、三十六小洞天（如霍桐山、东岳泰山、南岳衡山等）与七十二福地（如地肺山、盖竹山、青城山等），合称洞天福地。洞天福地之说把名山胜景与神仙信仰结合，道教宫观多择其地而建，如青城、龙虎、武当、茅山诸山皆在其中，对中国山水文化、旅游名胜的认知影响深远。',related:['daozang','longhushan','shangqing-pai']},
  {slug:'sanqing',name:'三清',pinyin:'Sān Qīng',english:'Three Pure Ones',category:'daoxue',shortDesc:'道教最高尊神：玉清元始天尊、上清灵宝天尊、太清道德天尊。',detail:'三清是道教尊奉的最高神祇，指玉清境元始天尊、上清境灵宝天尊、太清境道德天尊，分别居于清微天、禹余天、大赤天三清境，道教宫观主殿多称三清殿，塑三清像居中供奉。三清神格的形成与道教经教体系相关：元始天尊为道之化身、开天辟地之祖，灵宝天尊主度人经法，道德天尊即太上老君（老子神化）为道教教主；道教又有「一气化三清」之说，谓三清本为一体。三清信仰是道教神学成熟的标志，成为道教区别于其他宗教的象征性神系。',related:['siyu','laojun','daozang']},
  {slug:'siyu',name:'四御',pinyin:'Sì Yù',english:'Four Sovereigns',category:'daoxue',shortDesc:'辅佐三清的四大天帝：玉皇、紫微、勾陈、后土。',detail:'四御是道教仅次于三清的尊神，为总领天地的四位天帝，宫观中常于三清殿两侧配祀。其名目为：昊天金阙至尊玉皇大帝（总执天道，即民间所奉玉皇大帝）、中天紫微北极大帝（协助玉皇执掌天经地纬、日月星辰）、勾陈上宫天皇大帝（协助执掌南北极与天地人三才、主兵戈）、承天效法后土皇地祇（掌阴阳生育、山川大地，即后土娘娘）。四御之设把古代天帝信仰（昊天上帝）与星宿崇拜（紫微、勾陈皆星名）系统纳入道教神谱，反映道教「三清尊神、四御辅佐」的至上神结构。',related:['sanqing','laojun','liuding-liujia']},
  {slug:'laojun',name:'太上老君',pinyin:'Tài Shàng Lǎo Jūn',english:'Lord Lao (Deified Laozi)',category:'daoxue',shortDesc:'老子神格化的尊神，道教教主，三清之太清道德天尊。',detail:'太上老君是道教对老子（李耳）神格化的尊称。道教尊老子为教主与最高神之一：东汉张道陵创教奉老子为教祖，著《老子想尔注》谓「一散形为气，聚形为太上老君」；魏晋以降老君信仰益隆，居太清境为道德天尊，与元始、灵宝合称三清。道教传说老君屡降世度人，历代帝王朝多崇奉之：唐高祖尊老君为始祖，封太上玄元皇帝，宋真宗又封太上老君混元上德皇帝。老君像多为白发老翁骑青牛之形，道教宫观常设老君殿、炼丹处，太上老君已成为道教与中国民间信仰的标志性神祇。',related:['sanqing','dao','taishang-ganyingpian']},
  {slug:'liuding-liujia',name:'六丁六甲',pinyin:'Liù Dīng Liù Jiǎ',english:'Six Ding and Six Jia Generals',category:'daoxue',shortDesc:'道教护法神将：六丁阴神六甲阳神共十二位，供法师役使。',detail:'六丁六甲是道教护法神将的总称，共十二位：六丁为阴神玉女，即丁卯、丁丑、丁亥、丁酉、丁未、丁巳；六甲为阳神甲士，即甲子、甲戌、甲申、甲午、甲辰、甲寅。道教认为法师书符行法、步罡踏斗时可召遣六丁六甲随行护身、驱邪缚魅，符箓中常有六丁六甲符，斋醮科仪亦设其神位。六丁六甲之说源于干支神化：天干地支本为纪时符号，道教赋予其人格神性，配以姓名服色，遂成符箓派常用之神将；民间传说如《三国演义》中诸葛亮借东风亦托言六丁六甲，可见其影响。',related:['fulu','leifa','siyu']},
  {slug:'longhushan',name:'龙虎山',pinyin:'Lóng Hǔ Shān',english:'Mount Longhu',category:'daoxue',shortDesc:'正一道祖庭：张道陵炼丹处，历代天师世居，天师府所在。',detail:'龙虎山位于今江西鹰潭贵溪，是道教正一道的祖庭。相传东汉张道陵曾在此炼丹，丹成而龙虎现，山因以名；西晋永嘉后张氏后裔移居此山，历代天师世居山中，建上清宫与天师府，统领江南符箓道教，龙虎山遂成道教最负盛名的洞天福地，名列道教第二十九福地（一说三十二福地）。山中有天师府（历代天师起居之所，号称道教祖庭）、上清宫遗址、正一观及仙水岩悬棺等胜迹。龙虎山与茅山、阁皂山并称符箓三山，今为中国道教正一派中心与著名旅游胜地。',related:['zhengyi-dao','tianshi-dao','dongtian-fudi']},
  // ===== 道学补充 · 人物科仪法 (12) =====
  {slug:'tianshi',name:'天师',pinyin:'Tiān Shī',english:'Celestial Master',category:'daoxue',shortDesc:'道教宗师称号：张道陵称祖天师，其后裔世袭天师号。',detail:'天师原为对有道高士的尊称，义为代天行化之师，道教中特指张道陵一系的称号。东汉张道陵得太上老君授正一盟威之道，世称张天师、祖天师，其后子孙世代承袭天师之位，居江西龙虎山，主领江南道教符箓之事；元代封正一教主，明初改封大真人，然民间仍称天师。历代天师多有赐号，如三十代天师张继先、四十三代天师张宇初皆以道法文章著称。天师一系传承近两千年不绝，为世界罕见的世袭宗教领袖制度，今六十三代天师后裔居台湾，龙虎山另立天师府主持教务。',related:['tianshi-dao','zhengyi-dao','longhushan']},
  {slug:'shoulu',name:'授箓',pinyin:'Shòu Lù',english:'Receiving the Registers',category:'daoxue',shortDesc:'正一道士受法箓之仪：得箓职神将乃可召神行法。',detail:'授箓是正一道的重要仪典，指道士经拜师受戒后，由法师授予法箓（记载神将功曹名号与受箓者名籍的法券）与职牒，取得神职与行法资格。道教认为箓为「天地之神真之官属」，授箓之后方有神将吏兵随身护持，可以召神劾鬼、行符作法；未受箓者不得为人行法。授箓有阶次之别，历代有六阶、七阶之说，如初授三五都功箓、再授正一盟威箓，上清派则有上清大洞箓等高阶。授箓与传戒相对：全真重传戒，正一重授箓，今龙虎山天师府仍定期举行授箓大典。',related:['zhengyi-dao','fulu','zhaijiao']},
  {slug:'bugang-tadou',name:'步罡踏斗',pinyin:'Bù Gāng Tà Dǒu',english:'Pacing the Guideline and Treading the Dipper',category:'daoxue',shortDesc:'斋醮中法师按星斗之位步行的法术步伐，以召神遣将。',detail:'步罡踏斗是道教斋醮行法的核心仪范，指法师在坛场中按北斗七星及九宫八卦之位，以特殊步法行走，如踏星斗于足下，故称踏罡步斗（罡即北斗之柄，斗即星斗）。步法源自禹步，讲究「三步九迹」，履星步斗以通神召将、驱邪镇煞，各派罡法有斗罡、河图罡、八卦罡等名目。行法时法师仗剑持符，口念咒语，脚踩罡步，配合掐诀存想，如身在星斗间运转，是道教法术最具仪式感的部分，也是斋醮科仪、法事表演中最引人注目的场景。',related:['yubu','qiajue','leifa']},
  {slug:'yubu',name:'禹步',pinyin:'Yǔ Bù',english:'Yu Step (Shamanic Pace)',category:'daoxue',shortDesc:'巫道之步法：相传大禹治水所创，三步九迹，步罡之基础。',detail:'禹步是道教法术中最基本的步伐，相传大禹治水时因足跛而行此步，巫者效之以禁咒驱邪，故称禹步。其法大体为：先举左足，三步九迹，或进或退，如北斗之形，行时配合咒语存想，谓可通神禁鬼、制伏邪魅。《抱朴子》载有禹步之法并谓「凡作天下百术，皆宜知禹步」。禹步源于远古巫觋踏舞，道教承之而为步罡踏斗的雏形，是法术仪式中上接巫术、下达科仪的关节；后世戏曲中道人作法走的「罡步」即由禹步演化。',related:['bugang-tadou','qiajue','fulu']},
  {slug:'qiajue',name:'掐诀',pinyin:'Qiā Jué',english:'Finger Seals (Qia Jue)',category:'daoxue',shortDesc:'以手指掐结诀目（手印），配合咒语符法召神遣将之法。',detail:'掐诀又称捻诀、捏诀、结手印，是道教法术中与咒语、步罡相配合的重要手法。诀者，诀窍之义，法师以手指掐按十二地支、九宫八卦等部位，或屈伸指节结成各种诀目（如斗诀、剑诀、雷诀、天罡诀等），每一诀目代表相应的神将或法力，掐诀即以手印与神沟通、布气行法。掐诀须默念咒语、存想神气贯注指端，符法、召将、驱邪、治病时皆须掐诀配合。道教诀目名目繁多，向为口传心授之秘，与密宗手印有相似处而自成体系。',related:['bugang-tadou','yubu','fulu']},
  {slug:'shougengshen',name:'守庚申',pinyin:'Shǒu Gēng Shēn',english:'Guarding the Gengshen Night',category:'daoxue',shortDesc:'道教习俗：庚申之夜彻夜不眠，使三尸不得离身上天言罪。',detail:'守庚申是道教修炼与民俗合一的斋戒习俗。道教认为人身中有三尸虫（三彭），每逢庚申日趁人熟睡时离体上天，向天帝告发人的罪过，减人禄命；故信奉者于庚申之夜彻夜端坐不眠，令三尸无法出窍，称为守庚申，又称守三尸。此俗南北朝已流行，至唐尤盛，宫观民间多于庚申日设斋会、诵经守夜，谓能却病延年、长生不死。守庚申反映道教以「庚申」日干支节律配合养生与罪福观念的传统，唐末五代内丹兴起后渐衰，然民间仍有「庚申守夜」之遗俗。',related:['sanshi','chengfu','taishang-ganyingpian']},
  {slug:'sanshi',name:'三尸',pinyin:'Sān Shī',english:'Three Corpses (San Shi)',category:'daoxue',shortDesc:'道教所说人身中之三尸虫：彭琚彭质彭矫，主欲好食，伺睡言罪。',detail:'三尸又称三虫、三彭，是道教认为寄居人体内、危害生命的三种虫。三尸各有所好：上尸名彭琚（一作彭居），居人头中，好宝物，使人眼昏齿摇；中尸名彭质，居人腹中，好五味，使人脏腑混乱；下尸名彭矫，居人足中，好色欲，使人淫乱贪残。三尸以人欲望为养，每逢庚申日趁人熟睡离体上天言人罪过，减人寿算，故道教有守庚申、服符药以斩三尸之法，谓三尸去则「尸虫灭而道气生」。斩三尸为道教早期修炼的重要内容，常与辟谷守庚申相提并论。',related:['shougengshen','bigu','chengfu']},
  {slug:'zhensren',name:'真人',pinyin:'Zhēn Rén',english:'Perfected Person (Zhen Ren)',category:'daoxue',shortDesc:'修真得道之人的称号，庄子谓古之真人，后世尊为仙号。',detail:'真人是道教对修真得道者的尊称。《庄子·大宗师》描绘古之真人「不逆寡，不雄成，不谟士」「登高不栗，入水不濡，入火不热」，能「息以踵」而行真人之息，是体道合一、超脱生死的人格典范。《黄帝内经》亦谓真人「提挈天地，把握阴阳，呼吸精气，独立守神，肌肉若一，故能寿敝天地」。道教承此而以真人称得道仙真与高道：如庄子被尊为南华真人、张伯端为紫阳真人、丘处机为长春真人，封号中「真人」品位仅次于帝君，与仙人、天师同为道教仙真的品级称号。',related:['xian-wudeng','dao','quanzhen-dao']},
  {slug:'yuhua',name:'羽化',pinyin:'Yǔ Huà',english:'Feathered Transformation (Death of a Taoist)',category:'daoxue',shortDesc:'道士去世的讳称：如鸟生羽翼而飞升，亦指成仙。',detail:'羽化本指飞升成仙，道教谓仙人如鸟生羽翼而升天，故称羽化登仙；后世因以羽化为道士死亡的讳称，谓其人已脱去躯壳、化仙而去。称道士去世为羽化，与称和尚去世为圆寂、称帝王去世为驾崩相类，是宗教的敬语。传说中修道者羽化有多种形式：或白日飞升，或尸解（如蝉蜕），或坐化而逝，道教史传每记高道临终异香满室、颜色如生等祥瑞，以示羽化之验。今之道教宫观讣告、墓志仍多用「羽化」「仙逝」之词，为道教生死观的典型表达。',related:['shijie','zhensren','longmen-pai']},
  {slug:'baxian',name:'八仙',pinyin:'Bā Xiān',english:'Eight Immortals',category:'daoxue',shortDesc:'民间道教神仙群体：铁拐李汉钟离张果老吕洞宾何仙姑等八位。',detail:'八仙是道教传说中最脍炙人口的神仙群体，通行说法为：铁拐李、汉钟离（钟离权）、张果老、吕洞宾、何仙姑、蓝采和、韩湘子、曹国舅。八仙各有出身与法器（暗八仙：葫芦、扇、渔鼓、宝剑、荷花、花篮、洞箫、玉板），故事自唐宋渐次成型、明代定型，吴元泰《东游记》叙八仙过海故事使其家喻户晓。八仙多由凡人修炼成仙，象征男女老幼富贵贫贱皆可修道，深合道教普度精神；其中钟离权、吕洞宾为全真道所尊五祖之二，八仙信仰遂与内丹道派合流，民间庙会、戏曲、年画中八仙形象经久不衰。',related:['wuzu-qizhen','xian-wudeng','zhensren']},
  {slug:'changsheng-jiushi',name:'长生久视',pinyin:'Cháng Shēng Jiǔ Shì',english:'Longevity and Lasting Vigor',category:'daoxue',shortDesc:'道德经语：深根固柢长生久视之道，道教长生追求的经典出处。',detail:'长生久视出自《道德经》第五十九章，老子论治人事天莫若啬（爱惜精气）：「是谓深根固柢，长生久视之道。」视即活，久视谓寿命绵长而神志清明，与「长生不死」之欲求不同，老子之意在啬精爱气、根深柢固，则生命自然长久。道教承此而追求长生久视，以内丹炼养、服食导引为方，把「长生久视」作为修道的根本目标；庄子则谓「千岁厌世，去而上仙」，道教遂由养生之长生发展出肉身成仙的信仰。此语流传极广，成为道教与中华养生文化「长生不老」观念的经典出处。',related:['wuwei','jingqishen','tuna']},
  {slug:'gengshenri',name:'庚申日',pinyin:'Gēng Shēn Rì',english:'Gengshen Day',category:'daoxue',shortDesc:'六十甲子中干支俱阳之日，道教以为三尸上天言罪之日。',detail:'庚申日是干支纪日中天干庚、地支申相配之日，六旬中每逢庚申（约六十日一次）。道教认为人身三尸虫（三彭）每逢庚申日便乘人睡眠离体上天，向天帝陈说人之罪过，以减人禄算，故修道者于庚申日须守夜不眠、斋戒诵经，使三尸不得出窍，谓之守庚申；道教又有庚申经、庚申会等专为是日而设的经典法会。唐宋时守庚申之俗极为流行，宫廷民间皆行之。庚申日在道教节律信仰中占有特殊位置，与守庚申、三尸之说三位一体，为道教时间民俗的独特现象。',related:['shougengshen','sanshi','chengfu']},
  {slug:'qingwei',name:'清微派',pinyin:'Qīng Wēi Pài',english:'Pure Tenuity School',category:'daoxue',shortDesc:'宋元雷法道派之一，尊元始天尊为祖，以清微雷法名世。',detail:'清微派是宋元间兴起的道教雷法宗派，与神霄派并称雷法两大流派。清微派自称其法出于元始天尊，经玉清、上清、太清而至唐代祖舒开派传世，宋代黄舜申（号雷渊真人）集其大成，著《清微仙谱》等，使清微法大行。清微派重内炼外法，主张以身心合道、以静定通神，行法先内炼五脏之气，故有「清微之要，在乎澄心」「道法本无多，南辰贯北河」之说；其法与神霄略异而宗旨相近，皆以内丹为体、符法为用。元以后清微诸派多并入正一，其雷法理论影响深远。',related:['shenxiao-pai','leifa','neidan']},
  {slug:'dengxianlu',name:'登仙',pinyin:'Dēng Xiān',english:'Ascending to Immortality',category:'daoxue',shortDesc:'成仙升天之意：白日飞升、羽化登仙皆为登仙之说。',detail:'登仙指修道者功德圆满、升入仙籍仙境，即成仙之义，又称飞升、升仙。道教传说登仙形式多样：功行圆满者白日飞升，举形升虚，如传说中黄帝乘龙升天；或尸解仙去，如蝉蜕而神化；或死后安葬而空棺，谓尸解登仙。魏晋神仙传记多载「白日登仙」「举家飞升」之事，如许逊拔宅飞升的传说即登仙信仰的典型。登仙为道教修炼的终极追求，与之相应的是「仙」之品级（鬼仙人仙地仙神仙天仙）与洞天福地的归宿之说；登仙观念深刻影响了中国文学中羽人、飞仙的想象。',related:['shijie','yuhua','xian-wudeng']},
];
